    /// <summary>Custom block <c>move (action) - (input) - (name)</c> (run without screen refresh).</summary>
    void Move(Value action, Value input, Value name)
    {
        if (Eq(action, "selectdata"))
        {
            EditAddress(31, input);
            EditAddress(34, stage.ramEngineData.Item(32));
        }
        else
        {
            if (Eq(action, "selectfile"))
            {
                EditAddress(32, input);
            }
            else
            {
                if (Eq(action, "move"))
                {
                    stage.temp.DeleteAll();
                    stage.fileMoveIndex = stage.ramEngineData.Item(62);
                    for (double i1 = 0, times1 = Round(2); i1 < times1; i1++)
                    {
                        stage.temp.Add(stage.engineFiles.Item(stage.fileMoveIndex));
                        stage.fileMoveIndex = stage.fileMoveIndex.Num + 1;
                    }
                    stage.fileOldFile = stage.engineFiles.Item(stage.ramEngineData.Item(68));
                    stage.fileFileAddress = stage.engineFiles.Item(stage.ramEngineData.Item(64));
                    stage.fileDataName = stage.engineFiles.Item(stage.ramEngineData.Item(62).Num + 1);
                    if (Eq(stage.ramEngineData.Item(66), 0))
                    {
                        DeleteNameIfDataObject("data", stage.ramEngineData.Item(62), stage.engineFiles.IndexOf(stage.fileOldFile), "");
                        stage.fileDataName = "";
                        InsertDataToFile(stage.fileFileAddress, stage.temp.Item(1), stage.temp.Item(2));
                    }
                    else
                    {
                        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.temp.Item(2), "", "", "", "");
                        stage.fileJoinIndex = 2;
                        stage.fileJoin = "";
                        for (double i1 = 0, times1 = Round(stage.decodedElements.Length - 1); i1 < times1; i1++)
                        {
                            stage.fileJoin = stage.fileJoin.Str + ("," + stage.decodedElements.Item(stage.fileJoinIndex).Str);
                            stage.fileJoinIndex = stage.fileJoinIndex.Num + 1;
                        }
                        InsertDataToFile(stage.engineFiles.Item(stage.engineFiles.IndexOf(stage.fileFileAddress)), stage.temp.Item(1), name.Str + (stage.fileJoin.Str + ","));
                    }
                    if (Eq(input, ""))
                    {
                        EditAddress(16, stage.engineFiles.IndexOf(stage.fileFileAddress));
                    }
                    else
                    {
                        EditAddress(16, stage.engineFiles.IndexOf(stage.fileOldFile));
                    }
                    stage.temp.DeleteAll();
                }
            }
        }
    }

    /// <summary>Custom block <c>Configuration: Tabs (Tab)</c> (run without screen refresh).</summary>
    void ConfigurationTabs(Value tab)
    {
        stage.configureTab2 = "?";
        if (Eq(tab, "engine"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(42);
            if (Eq(stage.configureTab2, "*config*"))
            {
                ConfigureEngine1TimeConfigure();
            }
            if (Eq(stage.configureTab2, "general"))
            {
                EngineGeneral();
            }
            if (Eq(stage.configureTab2, "mode7"))
            {
                EngineMode7();
            }
            if (Eq(stage.configureTab2, "2dseg"))
            {
                Engine2dseg();
            }
            if (Eq(stage.configureTab2, "raster"))
            {
                EngineRaster();
            }
        }
        if (Eq(tab, "user interface"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(44);
            if (Eq(stage.configureTab2, "general"))
            {
                UserInterfaceGeneral();
            }
            if (Eq(stage.configureTab2, "theme"))
            {
                UserInterfaceTheme();
            }
            if (Eq(stage.configureTab2, "optimize"))
            {
                UserInterfaceOptimize();
            }
        }
        if (Eq(tab, "data management"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(46);
            if (Eq(stage.configureTab2, "format"))
            {
                DataFormat();
            }
            if (Eq(stage.configureTab2, "general"))
            {
                DataGeneral();
            }
        }
        if (Eq(tab, "file management"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(48);
            if (Eq(stage.configureTab2, "general"))
            {
                FileManagementGeneral();
            }
        }
        if (Eq(tab, "general settings"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(50);
            if (Eq(stage.configureTab2, "general"))
            {
                GeneralGeneral();
            }
        }
        if (Eq(tab, "export program"))
        {
            stage.configureTab2 = stage.ramEngineData.Item(52);
            if (Eq(stage.configureTab2, "general"))
            {
                ExportGeneral();
            }
        }
    }

