    /// <summary>Custom block <c>engine.Screen_render (full_Screen)</c> (run without screen refresh).</summary>
    void EngineScreenRender(Value fullScreen)
    {
        EngineDimensions(fullScreen);
        if (!Eq(stage.engineCamera, "no camera"))
        {
            RenderUpdater();
            stage.engineSkyboxScale = 0.325 + (0.1 * Num(Eq(stage.editorTab, "model"))) + Nz(Math.Abs(stage.engineScreenTopleftx.Num - stage.engineScreenBottomrightx.Num) / 512) + Nz(Math.Abs(stage.engineScreenToplefty.Num - stage.engineScreenBottomrighty.Num) / 512);
            if ((!stage.renderQueue.Contains("skybox")) || Eq(stage.ramEngineData.Item(140), "solid color"))
            {
                SetPenSize(625);
                if ((!stage.renderQueue.Contains("skybox")) || Eq(stage.ramEngineData.Item(180), "black"))
                {
                    SetPenColor("#000000");
                }
                else
                {
                    if (Eq(stage.ramEngineData.Item(180), "white"))
                    {
                        SetPenColor("#ffffff");
                    }
                    else
                    {
                        SetPenColor("#98c8ff");
                    }
                }
                GoTo(0, 0);
                PenDown();
                PenUp();
            }
            else
            {
                if (Eq(stage.ramEngineData.Item(140), "2d skybox"))
                {
                    stage.engineDrawx = -1;
                    for (double i1 = 0, times1 = Round(2); i1 < times1; i1++)
                        // EDITED: the sky image stops sliding past 45 degrees so its edge never shows when looking far up/down.
                    {
                        Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_engine.skybox_1", stage.engineDrawx.Num * (256 * stage.engineSkyboxScale.Num) + (Nz(Mod(stage.ramEngineData.Item(118).Num * -3, 256)) * stage.engineSkyboxScale.Num) + stage.engineScreenMidx.Num, stage.engineScreenMidy.Num + (-1 * Math.Clamp(stage.ramEngineData.Item(120).Num, -45, 45)), 90, 100.5 * stage.engineSkyboxScale.Num, 0, 15, 0, "", "", 1, "", "");
                        stage.engineDrawx = stage.engineDrawx.Num + 1;
                    }
                }
                else
                {
                    Engine3Dskybox();
                }
            }
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_engine.ground", stage.engineScreenMidx, -1.5 * stage.ramEngineData.Item(120).Num, 90, 115 * stage.engineSkyboxScale.Num, 25 + (50 * Num(Eq(stage.ramEngineData.Item(180), "white") && Eq(stage.ramEngineData.Item(140), "solid color"))), "", 0, "", "", 1, "", "");
            if (Eq(stage.guiFreeze, 0) || Gt(stage.guiPopuptransparency, 1))
            {
                stage.engineScreenTimestamp = stage.engineScreenTimestamp.Num + 1;
            }
            stage.engineFov = stage.engineFov.Num + (-45 * Num(Eq(stage.ramEngineData.Item(178), 0)));
            if (Eq(stage.guiFreeze, 0) || Gt(stage.guiPopuptransparency, 1))
            {
                Engine3Drender();
            }
            stage.engineFov = stage.engineFov.Num + (45 * Num(Eq(stage.ramEngineData.Item(178), 0)));
            stage.engineStepx = Nz((stage.engineScreenBottomrightx.Num - stage.engineScreenTopleftx.Num) / 480) / stage.engineRes.Num;
            stage.engineStepy = Nz((stage.engineScreenToplefty.Num - stage.engineScreenBottomrighty.Num) / 360) / stage.engineRes.Num;
            stage.engineDrawy = 0;
            SetPenSize(Nz((0.85 + (stage.engineFullscreen.Num * 0.3)) / stage.engineRes.Num));
            for (double i1 = 0, times1 = Round(stage.engineScreenChannelcolumn.Num - 1); i1 < times1; i1++)
            {
                stage.engineDrawx = 1;
                stage.enginePrevPixelTimer = stage.engineScreenTimestamp;
                SetPenParam(PenParam.Transparency, 100);
                SetY((stage.engineScreenToplefty.Num - (stage.engineDrawy.Num * stage.engineStepy.Num)) * 1.01);
                PenDown();
                stage.enginePrevPixel = 0;
                for (double i2 = 0, times2 = Round(stage.engineScreenChannelrow.Num); i2 < times2; i2++)
                {
                    stage.engineScreenPixel = stage.engineDrawx.Num + (stage.engineDrawy.Num * stage.engineScreenChannelrow.Num + (2 * stage.engineScreenChannel.Num));
                    stage.enginePrevPixelTimer = stage.screenRenderer.Item(stage.engineScreenPixel.Num - 1 - (2 * stage.engineScreenChannel.Num));
                    stage.engineNextPixelTimer = stage.screenRenderer.Item(stage.engineScreenPixel.Num + 1 - (2 * stage.engineScreenChannel.Num));
                    if ((Lt(stage.engineNextPixelTimer, stage.engineScreenTimestamp) || (!(Eq(stage.enginePrevPixelTimer, stage.engineScreenTimestamp) && (Eq(stage.screenRenderer.Item(stage.engineScreenPixel.Num + (1 * stage.engineScreenChannel.Num)), stage.enginePrevBright) && Eq(stage.enginePrevPixel, stage.screenRenderer.Item(stage.engineScreenPixel)))))) && Eq(stage.screenRenderer.Item(stage.engineScreenPixel.Num - (2 * stage.engineScreenChannel.Num)), stage.engineScreenTimestamp))
                    {
                        SetX(stage.engineDrawx.Num * stage.engineStepx.Num + stage.engineScreenTopleftx.Num);
                        SetPenColor(stage.screenRenderer.Item(stage.engineScreenPixel));
                        ChangePenParam(PenParam.Brightness, stage.screenRenderer.Item(stage.engineScreenPixel.Num + (1 * stage.engineScreenChannel.Num)).Num);
                    }
                    else
                    {
                        SetPenParam(PenParam.Transparency, 100 * Num(Lt(stage.screenRenderer.Item(stage.engineScreenPixel.Num - (2 * stage.engineScreenChannel.Num)), stage.engineScreenTimestamp)));
                    }
                    stage.enginePrevPixel = stage.screenRenderer.Item(stage.engineScreenPixel);
                    stage.enginePrevBright = stage.screenRenderer.Item(stage.engineScreenPixel.Num + (1 * stage.engineScreenChannel.Num));
                    stage.engineDrawx = stage.engineDrawx.Num + 1;
                }
                stage.enginePrevPixel = 0;
                EngineDrawpixel();
                PenUp();
                stage.engineDrawy = stage.engineDrawy.Num + 1;
            }
            EngineRenderEngineSprites();
        }
        else
        {
            if (Eq(stage.allExportState, 0))
            {
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_gui.contrast", 0, 0, 90, 100, 0, -100, 0, "", "", "", "", "");
                TextOnScaleCenterGbcCursorLimitScroll("no camera assigned, assign one in the scene editor or through code", stage.engineScreenMidx, stage.engineScreenMidy, 0.43, 1, "", "", 100, "", "", 1, "", "");
                TextOnScaleCenterGbcCursorLimitScroll("to create a camera, choose the camera tool next to", stage.engineScreenMidx, stage.engineScreenMidy.Num - 15, 0.5, 1, "", "", 100, "", "", 1, "", "");
                TextOnScaleCenterGbcCursorLimitScroll("the \"object\" tool in the toolbar. name it, and then", stage.engineScreenMidx, stage.engineScreenMidy.Num - 30, 0.5, 1, "", "", 100, "", "", 1, "", "");
                TextOnScaleCenterGbcCursorLimitScroll("click on it and choose assign camera.", stage.engineScreenMidx, stage.engineScreenMidy.Num - 45, 0.5, 1, "", "", 100, "", "", 1, "", "");
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_gui.screen", -68, 100 + stage.guiMainMargin.Num, -90, 100, 50, "", "", "", "", "", "", "");
                Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_gui.screen", -68, -100 - stage.guiMainMargin.Num, 90, 100, 50, "", "", "", "", "", "", "");
            }
        }
        if (stage.renderQueue.Contains("bone tree"))
        {
            stage.engineCamxsin = Sin(stage.ramEngineData.Item(118).Num + 0);
            stage.engineCamxcos = Cos(stage.ramEngineData.Item(118).Num + 0);
            RenderBoneTree();
        }
        stage.engineTick = stage.engineTick.Num + 1;
        if (Eq(stage.engineFullscreen, 0))
        {
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_gui.screen", -68, 100 + stage.guiMainMargin.Num, -90, 100, 50, "", "", "", "", "", "", "");
            Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_gui.screen", -68, -100 - stage.guiMainMargin.Num, 90, 100, 50, "", "", "", "", "", "", "");
        }
    }

