    {
        stage.engineScreenChannel = Math.Floor(480 * stage.engineRes.Num) * Math.Floor(360 * stage.engineRes.Num);
        stage.screenRenderer.DeleteAll();
        for (double i1 = 0, times1 = Round(4 * stage.engineScreenChannel.Num); i1 < times1; i1++)
        {
            stage.screenRenderer.Add(0);
        }
        stage.engineScreenTimestamp = 0;
