        stage.engineScreenChannelcolumn = Math.Floor(360 * stage.engineRes.Num);
    }

    /// <summary>Custom block <c>engine.pixel (x) (y) (z) color (rgb) (brightness) shadow (shadow)</c> (run without screen refresh).</summary>
    void EnginePixelColorShadow(Value x, Value y, Value z, Value rgb, Value brightness, Value shadow)
    {
        stage.engineScreenPixel = 1 + Round((x.Num + 240) * stage.engineRes.Num) + (Round((180 - y.Num) * stage.engineRes.Num) * stage.engineScreenChannelrow.Num);
        if ((Gt(rgb, 1) && (Lt(Math.Abs(x.Num), 240) && Lt(Math.Abs(y.Num), 180))) && ((Gt(stage.screenRenderer.Item(stage.engineScreenPixel.Num + stage.engineScreenChannel.Num), z) && Eq(stage.screenRenderer.Item(stage.engineScreenPixel), stage.engineScreenTimestamp)) || Lt(stage.screenRenderer.Item(stage.engineScreenPixel), stage.engineScreenTimestamp)))
        {
            if (Eq(shadow, 1))
            {
                stage.screenRenderer.Replace(stage.engineScreenPixel, stage.engineScreenTimestamp);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + stage.engineScreenChannel.Num, z);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + (stage.engineScreenChannel.Num * 2), 1 + stage.screenRenderer.Item(stage.engineScreenPixel.Num + (stage.engineScreenChannel.Num * 2)).Num);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + (stage.engineScreenChannel.Num * 3), brightness.Num + stage.engineShadow.Num);
            }
            else
            {
                stage.screenRenderer.Replace(stage.engineScreenPixel, stage.engineScreenTimestamp);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + stage.engineScreenChannel.Num, z);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + (stage.engineScreenChannel.Num * 2), rgb);
                stage.screenRenderer.Replace(stage.engineScreenPixel.Num + (stage.engineScreenChannel.Num * 3), brightness);
            }
        }
    }

    /// <summary>Custom block <c>engine.3Drender</c> (run without screen refresh).</summary>
    void Engine3Drender()
    {
        stage.engineCameraDirX = stage.ramEngineData.Item(118);
        stage.engineCameraDirY = stage.ramEngineData.Item(120);
        stage.engineCameraX = stage.ramEngineData.Item(112);
        stage.engineCameraY = stage.ramEngineData.Item(114);
        stage.engineCameraZ = stage.ramEngineData.Item(116);
        if (stage.renderQueue.Contains("grid") && (!stage.renderQueue.Contains("mode7")))
        {
            EngineMode7UseScreenBufferTransparent(stage.engineRes, stage.engineFov, 0, "");
        }
        else
        {
            if (stage.renderQueue.Contains("scenegrid") && (!stage.renderQueue.Contains("mode7")))
            {
                EngineMode7UseScreenBufferTransparent(stage.engineRes, stage.engineFov, 0, 1);
            }
        }
        if (Contains(stage.engineType.Str, "m") && stage.renderQueue.Contains("mode7"))
        {
            EngineMode7UseScreenBufferTransparent(stage.engineRes, stage.engineFov, 1, "");
        }
        if ((Contains(stage.engineType.Str, "t") && stage.renderQueue.Contains("2dtile")) && (Contains(stage.engineType.Str, "s") && stage.renderQueue.Contains("2dseg")))
        {
            stage.engineDrawx = -240;
            stage.engineCamxsin = Sin(stage.ramEngineData.Item(118).Num + 90);
            stage.engineCamxcos = Cos(stage.ramEngineData.Item(118).Num + 90);
            stage.engineRayMode7vecx1 = Nz(Sin(stage.ramEngineData.Item(118).Num + 90)) * -240 - (Nz(Cos(stage.ramEngineData.Item(118).Num + 90)) * stage.engineFov.Num);
            stage.engineRayMode7vecy1 = Nz(Cos(stage.ramEngineData.Item(118).Num + 90)) * -240 + (Nz(Sin(stage.ramEngineData.Item(118).Num + 90)) * stage.engineFov.Num);
            stage.engineRayMode7vecx2 = Nz(Sin(stage.ramEngineData.Item(118).Num + 90)) * 240 - (Nz(Cos(stage.ramEngineData.Item(118).Num + 90)) * stage.engineFov.Num);
