    /// <summary>Custom block <c>File.FindData (DataName)</c> (run without screen refresh).</summary>
    void FileFindData(Value dataName)
    {
        stage.fileLoadIndex = 0;
        stage.fileFound = 0;
        for (double i1 = 0, times1 = Round(stage.engineFiles.Length); i1 < times1; i1++)
        {
            stage.fileLoadIndex = stage.fileLoadIndex.Num + 1;
            if (Contains(stage.engineFiles.Item(stage.fileLoadIndex).Str, ","))
            {
                DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 0, ",", "", "");
                if (Eq(stage.decodedElements.Item(1), dataName))
                {
                    stage.fileFound = 1;
                    stage.fileFolderIndex = stage.fileLoadIndex;
                    for (double i2 = 0, times2 = Round(10000); i2 < times2; i2++)
                    {
                        stage.fileFolderIndex = stage.fileFolderIndex.Num + -1;
                        if (!Eq(Num(stage.engineFiles.Item(stage.fileFolderIndex.Num + 1).Str + "") - 123456789, -123456789))
                        {
                            stage.fileFilename = stage.engineFiles.Item(stage.fileFolderIndex);
                            return;
