                }
            }
        }
        stage.fileLoadIndex = 0;
    }

    /// <summary>Custom block <c>engine.free_camera (speed) (turn)</c> (run without screen refresh).</summary>
    void EngineFreeCamera(Value speed, Value turn)
    {
        CreateAddress("engine.camera_direction_z", 0, 61);
        if ((Eq(stage.editorModelType, "3d") && Eq(stage.loadedModels.Item(4), "billboard")) && Eq(stage.editorTab, "model"))
        {
            CreateAddress("engine.camera_direction_x", 0, 59);
        }
        else
        {
            // EDITED: hold the right mouse button and drag to turn (was: left/right arrow keys).
            CreateAddress("engine.camera_direction_x", MouseLookX() + stage.ramEngineData.Item(118).Num, 59);
        }
        // EDITED: drag up/down with the right mouse button to look up/down (was: up/down arrow keys).
        CreateAddress("engine.camera_direction_y", MouseLookY() + stage.ramEngineData.Item(120).Num, 60);
        if (Eq(1, 0))
        {
            CreateAddress("engine.camera_direction_x", MouseX, 59);
            CreateAddress("engine.camera_direction_y", MouseY / 2, 60);
        }
        // EDITED: up/down limit is MaxCameraPitch (90, like Unity) instead of 45.
        if (Gt(stage.ramEngineData.Item(120), MaxCameraPitch))
        {
            CreateAddress("engine.camera_direction_y", MaxCameraPitch, 60);
        }
        if (Lt(stage.ramEngineData.Item(120), -MaxCameraPitch))
        {
            CreateAddress("engine.camera_direction_y", -MaxCameraPitch, 60);
        }
        CreateAddress("engine.camera_x", (Nz(Sin(90 + stage.ramEngineData.Item(118).Num)) * (Num(KeyPressed("d")) - Num(KeyPressed("a")))) * speed.Num + stage.ramEngineData.Item(112).Num, 56);
        CreateAddress("engine.camera_z", (Nz(Cos(90 + stage.ramEngineData.Item(118).Num)) * (Num(KeyPressed("d")) - Num(KeyPressed("a")))) * speed.Num + stage.ramEngineData.Item(116).Num, 58);
        if (KeyPressed("space") && KeyPressed("`"))
        {
            CreateAddress("engine.camera_y", 0, 57);
        }
        else
        {
            CreateAddress("engine.camera_y", (Num(KeyPressed("space")) - Num(KeyPressed("shift" + ""))) * speed.Num + stage.ramEngineData.Item(114).Num, 57);
            if (Lt(stage.ramEngineData.Item(114), -0.25))
            {
                CreateAddress("engine.camera_y", -0.25, 57);
            }
        }
        CreateAddress("engine.camera_x", (Nz(Sin(stage.ramEngineData.Item(118).Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * speed.Num + stage.ramEngineData.Item(112).Num, 56);
        CreateAddress("engine.camera_z", (Nz(Cos(stage.ramEngineData.Item(118).Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * speed.Num + stage.ramEngineData.Item(116).Num, 58);
        if (KeyPressed("h"))
        {
            CreateAddress("engine.camera_x", 0, 56);
            CreateAddress("engine.camera_y", 0, 57);
            CreateAddress("engine.camera_z", 0, 58);
            CreateAddress("engine.camera_direction_x", 0.01, 59);
            CreateAddress("engine.camera_direction_y", 0, 60);
            CreateAddress("engine.camera_direction_z", 0, 61);
        }
        // EDITED: mouse wheel zoom, middle-button pan, Q/E up/down while right-dragging (Custom/CameraControls.cs).
        UnityStyleCameraExtras(speed);
    }

