                    stage.modelTexturedat = stage.loadedTileMap.Item(3 * (stage.loadedTileMap.Item(2).Num * stage.loadedTileMap.Item(2).Num) + Math.Floor(x.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) + (Math.Floor(z.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) * stage.loadedTileMap.Item(2).Num));
                    StartSound("Windows Vista Beta IRBegin");
                }
                else
