                            {
                                if (Eq(tool, "tilechangey"))
                                {
                                    stage.loadedTileMap.Replace(Math.Floor(x.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) + (Math.Floor(z.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) * stage.loadedTileMap.Item(2).Num), y);
