                                    }
                                    else
                                    {
                                        if (Eq(tool, "tilechangetexture"))
                                        {
                                            stage.loadedTileMap.Replace(2 * (stage.loadedTileMap.Item(2).Num * stage.loadedTileMap.Item(2).Num) + Math.Floor(x.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) + (Math.Floor(z.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) * stage.loadedTileMap.Item(2).Num), texture);
                                            stage.loadedTileMap.Replace(3 * (stage.loadedTileMap.Item(2).Num * stage.loadedTileMap.Item(2).Num) + Math.Floor(x.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) + (Math.Floor(z.Num + Nz(stage.loadedTileMap.Item(2).Num / 2)) * stage.loadedTileMap.Item(2).Num), texturedat);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

