    /// <summary>Custom block <c>Delete (Branch) name (address) | if data (file) ||||| object (index)</c> (run without screen refresh).</summary>
    void DeleteNameIfDataObject(Value branch, Value address, Value file, Value index)
    {
        if (Gt(index, ""))
        {
            stage.scene.Replace(1, stage.scene.Item(1).Num - 1);
            for (double i1 = 0, times1 = Round(stage.scene.Item(index).Num); i1 < times1; i1++)
            {
                stage.scene.Delete(index);
            }
            EditAddress(9, 1);
            stage.fileDeleted = 1;
        }
        else
        {
            if (Gt(branch, ""))
            {
                if (Eq(branch, "data"))
                {
                    stage.fileDeleted = 1;
                    stage.engineFiles.Replace(file.Num + 1, stage.engineFiles.Item(file.Num + 1).Num - 2);
                    for (double i1 = 0, times1 = Round(2); i1 < times1; i1++)
                    {
                        stage.engineFiles.Delete(address);
                    }
                }
                else
                {
                    if (Eq(branch, "file"))
                    {
                        if (!Eq(stage.engineFiles.Item(address), stage.ramEngineData.Item(108)))
                        {
                            stage.fileDeleted = 1;
                            EditAddress(16, 1);
                            stage.fileReadIndex = stage.engineFiles.Item(address.Num + 1).Num + 3;
                            for (double i1 = 0, times1 = Round(stage.fileReadIndex.Num); i1 < times1; i1++)
                            {
                                stage.engineFiles.Delete(address);
                            }
                            stage.fileFiles = stage.fileFiles.Num + -1;
                        }
                        else
                        {
                            Message("can't delete a main directory", "_icon.bsod", "Error_1", 1);
                            stage.guiClickLimit = 0.5;
                        }
                    }
                }
            }
        }
    }

    /// <summary>Custom block <c>Render.Updater</c> (run without screen refresh).</summary>
    void RenderUpdater()
    {
        stage.renderQueue.DeleteAll();
        if (Eq(stage.editorTab, "scene"))
        {
            stage.renderQueue.Add("skybox");
            stage.objectIdx = 2;
            for (double i1 = 0, times1 = Round(stage.scene.Item(1).Num); i1 < times1; i1++)
            {
                if (Eq(stage.scene.Item(stage.objectIdx.Num + 5), "static(3d)"))
                {
                    FileFindData(stage.scene.Item(stage.objectIdx.Num + 7));
                    if (Eq(stage.fileFound, 1))
                    {
                        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, "", "", "");
                        if (Eq(stage.decodedElements.Item(2), "mode7"))
                        {
                            if (Eq(stage.scene.Item(stage.objectIdx.Num + 9), 1))
                            {
                                EngineLoadmodel(stage.scene.Item(stage.objectIdx.Num + 7));
                                stage.scene.Replace(stage.objectIdx.Num + 9, 0);
                            }
                            stage.renderQueue.Add("mode7");
                        }
                        if (Eq(stage.decodedElements.Item(2), "tile"))
                        {
                            if (Eq(stage.scene.Item(stage.objectIdx.Num + 9), 1))
                            {
                                EngineLoadmodel(stage.scene.Item(stage.objectIdx.Num + 7));
                                stage.scene.Replace(stage.objectIdx.Num + 9, 0);
                            }
                            stage.renderQueue.Add("2dtile");
                        }
                        if (Eq(stage.decodedElements.Item(2), "segment"))
                        {
                            if (Eq(stage.scene.Item(stage.objectIdx.Num + 9), 1))
                            {
                                EngineLoadmodel(stage.scene.Item(stage.objectIdx.Num + 7));
                                stage.scene.Replace(stage.objectIdx.Num + 9, 0);
                            }
                            stage.renderQueue.Add("2dseg");
                        }
                    }
                }
                else
                {
                    if (Eq(stage.scene.Item(stage.objectIdx.Num + 5), "3d"))
                    {
                        FileFindData(stage.scene.Item(stage.objectIdx.Num + 7));
                        if (Eq(stage.fileFound, 1))
                        {
                            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, "", "", "");
                            EngineLoad3dModelBone(stage.decodedElements.Item(1), "", "");
                            if (!stage.renderQueue.Contains("3d"))
                            {
                                stage.renderQueue.Add("3d");
                            }
                        }
                    }
                    if (Eq(stage.scene.Item(stage.objectIdx.Num + 5), "bone"))
                    {
                        FileFindData(stage.scene.Item(stage.objectIdx.Num + 7));
                        if (Eq(stage.fileFound, 1))
                        {
                            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, "", "", "");
                            EngineLoad3dModelBone(stage.decodedElements.Item(1), 1, "");
                        }
                    }
                }
                stage.objectIdx = stage.objectIdx.Num + stage.scene.Item(stage.objectIdx).Num;
            }
            if (Eq(stage.ramEngineData.Item(172), 1))
            {
                stage.renderQueue.Add("scenegrid");
            }
        }
        else
        {
            if (Eq(stage.modelLoaded, 1))
            {
                if (Eq(stage.editorModelType, "tile"))
                {
                    stage.renderQueue.Add("2dtile");
                    stage.renderQueue.Add("grid");
                }
                else
                {
                    if (Eq(stage.editorModelType, "mode7"))
                    {
                        stage.renderQueue.Add("mode7");
                    }
                    else
                    {
                        if (Eq(stage.editorModelType, "segment"))
                        {
                            stage.renderQueue.Add("2dseg");
                            stage.renderQueue.Add("grid");
                        }
                        else
                        {
                            if (Eq(stage.editorModelType, "bone"))
                            {
                                stage.renderQueue.Add("bone tree");
                            }
                            else
                            {
                                stage.renderQueue.Add("3d");
                            }
                            stage.renderQueue.Add("grid");
                        }
                    }
                }
            }
        }
        if (Eq(stage.editorTab, "scene"))
        {
            stage.renderQueue.Add("scene objects");
        }
        else
        {
            if (Eq(stage.editorTab, "model"))
            {
                if (Eq(stage.editorModelType, "segment"))
                {
                    stage.renderQueue.Add("segment objects");
                }
                if (Eq(stage.editorModelType, "3d"))
                {
                    if (Gt(stage.editorShowbone, 0))
                    {
                        if (Eq(stage.loadedBoneTree.Length, 1))
                        {
                            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.editorShowbone.Num + 0), 1, "", "", "");
                            stage.loadedBoneTree.DeleteAll();
                            stage.loadedBoneTree.Add(0);
                            EngineLoad3dModelBone(stage.decodedElements.Item(1), 1, "");
                        }
                        stage.renderQueue.Add("bone tree");
                    }
                }
            }
        }
        if (stage.renderQueue.Contains("2dtile"))
        {
            stage.engineTile2D = 1;
        }
        else
        {
            stage.engineTile2D = 0;
        }
        if (stage.renderQueue.Contains("2dseg"))
        {
            stage.engineSeg2D = 1;
        }
        else
        {
            stage.engineSeg2D = 0;
        }
    }

