    /// <summary>Custom block <c>Detect Key (special) game (game)</c> (run without screen refresh).</summary>
    void DetectKeyGame(Value special, Value game)
    {
        stage.inputSubmit = 0;
        stage.inputIndex = 1;
        stage.inputKey = "";
        while (!(Gt(stage.inputIndex, stage.keys.Length + 1) || (((!KeyPressed("" + ",")) || Eq(special, 1)) && (Gt(stage.inputIndex, 39 * Num(Eq(special, 0)) + (Num(Eq(special, 1)) * stage.keys.Length)) || KeyPressed(stage.keys.Item(stage.inputIndex))))))
        {
            stage.inputIndex = stage.inputIndex.Num + 1;
        }
        if (KeyPressed(stage.keys.Item(stage.inputIndex)))
        {
            stage.inputKey = stage.keys.Item(stage.inputIndex);
        }
        if (Eq(game, ""))
        {
            if (KeyPressed("space"))
            {
                if (Eq(special, 1))
                {
                    stage.inputKey = " ";
                }
                else
                {
                    stage.inputKey = "-";
                }
            }
            if (Eq(special, 0))
            {
                if (KeyPressed("left arrow") || KeyPressed("backspace" + ""))
                {
                    stage.inputDelete = "";
                    stage.inputIndex = 0;
                    for (double i1 = 0, times1 = Round(stage.ramEngineData.Item((stage.inputAddress.Num - 1) * 2 + 2).Str.Length - 1); i1 < times1; i1++)
                    {
                        stage.inputIndex = stage.inputIndex.Num + 1;
                        stage.inputDelete = stage.inputDelete.Str + LetterOf(stage.inputIndex.Num, stage.ramEngineData.Item((stage.inputAddress.Num - 1) * 2 + 2).Str);
                    }
                    EditAddress(stage.inputAddress, stage.inputDelete);
                }
                else
                {
                    if (KeyPressed("enter" + ""))
                    {
                        stage.inputSubmit = 1;
                    }
                    else
                    {
                        if (Lt(stage.ramEngineData.Item((stage.inputAddress.Num - 1) * 2 + 2).Str.Length, stage.inputLimit.Num + 1))
                        {
                            EditAddress(stage.inputAddress, stage.ramEngineData.Item((stage.inputAddress.Num - 1) * 2 + 2).Str + stage.inputKey.Str);
                        }
                        else
                        {
                            StartSound("Windows Vista Beta Exclamation");
                        }
                    }
                }
            }
        }
        else
        {
            if (KeyPressed("up arrow"))
            {
                stage.inputKey = "up";
            }
            if (KeyPressed("down arrow"))
            {
                stage.inputKey = "down";
            }
            if (KeyPressed("right arrow"))
            {
                stage.inputKey = "right";
            }
            if (KeyPressed("left arrow"))
            {
                stage.inputKey = "left";
            }
            if (KeyPressed("space"))
            {
                stage.inputKey = "space";
            }
        }
    }

