    /// <summary>Custom block <c>engine.load_3d_model (model) bone (bone) (object)</c> (run without screen refresh).</summary>
    void EngineLoad3dModelBone(Value model, Value bone, Value @object)
    {
        FileFindData(model);
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), "", "", "", "");
        if (Eq(bone, 1))
        {
            if (!stage.loadedBoneTree.Contains(model))
            {
                stage.loadedBoneTree.Replace(1, stage.loadedBoneTree.Item(1).Num + 1);
                stage.loadedBoneTree.Insert(stage.loadedBoneTree.Item(1).Num * 2, model.Str + @object.Str);
                stage.loadedBoneTree.Insert(stage.loadedBoneTree.Item(1).Num * 2 + 1, 0);
                if (!Eq(stage.decodedElements.Item(2), "0|"))
                {
                    stage.fileDat = stage.decodedElements.Item(2);
                    stage.proccessDecode = "";
                    stage.proccessDecodeIndex = 0;
                    stage.proccessLength = 0;
                    stage.engineModellength = 0;
                    stage.engineBoneindex = 1;
                    for (double i1 = 0, times1 = Round(stage.fileDat.Str.Length); i1 < times1; i1++)
                    {
                        stage.proccessDecode = stage.proccessDecode.Str + LetterOf(stage.proccessDecodeIndex.Num, stage.fileDat.Str);
                        if (Eq(LetterOf(stage.proccessDecodeIndex.Num + 1, stage.fileDat.Str), "|"))
                        {
                            if (!Eq(stage.engineModellength, 0))
                            {
                                if (Eq(Mod(stage.engineBoneindex.Num - 1, stage.engineBoneattributes.Num), 0))
                                {
                                    stage.loadedBoneTree.Add(stage.proccessDecode.Str + @object.Str);
                                }
                                else
                                {
                                    stage.loadedBoneTree.Add(stage.proccessDecode);
                                }
                            }
                            stage.proccessDecode = "";
                            stage.engineModellength = stage.engineModellength.Num + 1;
                            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
                            stage.engineBoneindex = stage.engineBoneindex.Num + 1;
                        }
                        stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
                    }
                    stage.loadedBoneTree.Replace(stage.loadedBoneTree.Item(1).Num * 2 + 1, stage.engineModellength.Num - 1);
                }
            }
        }
        else
        {
            if (!stage.loadedModels.Contains(model))
            {
                if (Eq(stage.decodedElements.Item(2), "billboard") || Eq(stage.decodedElements.Item(2), "3d"))
                {
                    stage.loadedModels.Replace(1, stage.loadedModels.Item(1).Num + 1);
                    stage.loadedModels.Insert(stage.loadedModels.Item(1).Num * 2, model);
                    if (Eq(stage.decodedElements.Item(2), "billboard"))
                    {
                        stage.loadedModels.Insert(stage.loadedModels.Item(1).Num * 2 + 1, 1);
                        stage.loadedModels.Insert(stage.loadedModels.Item(1).Num * 2 + 2, "billboard");
                    }
                    else
                    {
                        stage.loadedModels.Insert(stage.loadedModels.Item(1).Num * 2 + 1, 0);
                    }
                    if (!Eq(stage.decodedElements.Item(3), "0|"))
                    {
                        stage.fileDat = stage.decodedElements.Item(3);
                        stage.proccessDecode = "";
                        stage.proccessDecodeIndex = 0;
                        stage.proccessLength = 0;
                        stage.engineModellength = 0;
                        for (double i1 = 0, times1 = Round(stage.fileDat.Str.Length); i1 < times1; i1++)
                        {
                            stage.proccessDecode = stage.proccessDecode.Str + LetterOf(stage.proccessDecodeIndex.Num, stage.fileDat.Str);
                            if (Eq(LetterOf(stage.proccessDecodeIndex.Num + 1, stage.fileDat.Str), "|"))
                            {
                                if (!Eq(stage.engineModellength, 0))
                                {
                                    stage.loadedModels.Add(stage.proccessDecode);
                                }
                                stage.proccessDecode = "";
                                stage.engineModellength = stage.engineModellength.Num + 1;
                                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
                            }
                            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
                        }
                        stage.loadedModels.Replace(stage.loadedModels.Item(1).Num * 2 + 1, stage.engineModellength.Num - 1);
                    }
                }
            }
        }
    }

