    /// <summary>Custom block <c>engine.save3dmodel (name)</c> (run without screen refresh).</summary>
    void EngineSave3dmodel(Value name)
    {
        if (Eq(stage.editorModelType, "bone"))
        {
            stage.fileDat = stage.loadedBoneTree.Item(2).Str + ",|";
            stage.proccessDecodeIndex = 4;
            for (double i1 = 0, times1 = Round(stage.loadedBoneTree.Item(3).Num); i1 < times1; i1++)
            {
                stage.fileDat = stage.fileDat.Str + (stage.loadedBoneTree.Item(stage.proccessDecodeIndex).Str + "|");
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
            }
            stage.fileDat = stage.fileDat.Str + ",";
            FileFindData(stage.loadedBoneTree.Item(2));
            stage.loadedBoneTree.DeleteAll();
            stage.loadedBoneTree.Add(0);
        }
        else
        {
            stage.fileDat = stage.loadedModels.Item(2).Str + ",3d,|";
            stage.proccessDecodeIndex = 4;
            for (double i1 = 0, times1 = Round(stage.loadedModels.Item(3).Num); i1 < times1; i1++)
