    /// <summary>Custom block <c>Edit data in object (Object name) data (data name) (data val) operation (operation)</c> (run without screen refresh).</summary>
    void EditDataInObjectDataOperation(Value objectName, Value dataName, Value dataVal, Value operation)
    {
        stage.sceneObject = stage.scene.IndexOf(objectName.Str + ".start") - 1;
        stage.dataReturn = "null";
        for (double i1 = 0, times1 = Round(100); i1 < times1; i1++)
        {
            stage.sceneObject = stage.sceneObject.Num + 2;
            if (Eq(stage.scene.Item(stage.sceneObject), dataName))
            {
                if (Eq(operation, "set"))
                {
                    stage.scene.Replace(stage.sceneObject.Num + 1, dataVal);
                    stage.dataReturn = stage.scene.Item(stage.sceneObject.Num + 1);
                }
                else
                {
                    if (Eq(operation, "add"))
                    {
                        stage.scene.Replace(stage.sceneObject.Num + 1, stage.scene.Item(stage.sceneObject.Num + 1).Num + dataVal.Num);
                        stage.dataReturn = stage.scene.Item(stage.sceneObject.Num + 1);
                    }
                    else
                    {
                        if (Eq(operation, "mul"))
                        {
                            stage.scene.Replace(stage.sceneObject.Num + 1, stage.scene.Item(stage.sceneObject.Num + 1).Num * dataVal.Num);
                            stage.dataReturn = stage.scene.Item(stage.sceneObject.Num + 1);
                        }
                        else
                        {
                            if (Eq(operation, "read"))
                            {
                                stage.dataReturn = stage.scene.Item(stage.sceneObject.Num + 1);
                            }
                        }
                    }
                }
                return;
            }
        }
        if (!Eq(operation, "read"))
        {
            TerminalPrint("variable \"" + (dataName.Str + ("\" not found in " + objectName.Str)), 0);
        }
    }

