    /// <summary>Custom block <c>engine.savescript (file)</c> (run without screen refresh).</summary>
    void EngineSavescript(Value file)
    {
        stage.fileDat = file.Str + ",";
        stage.proccessDecodeIndex = 1;
        for (double i1 = 0, times1 = Round(stage.loadedTextEditor.Length); i1 < times1; i1++)
        {
            if (Eq(stage.loadedTextEditor.Item(stage.proccessDecodeIndex), ""))
            {
                stage.fileDat = stage.fileDat.Str + "\\n|";
            }
            else
            {
                stage.textIndex = 1;
                for (double i2 = 0, times2 = Round(stage.loadedTextEditor.Item(stage.proccessDecodeIndex).Str.Length); i2 < times2; i2++)
                {
                    if (Eq(LetterOf(stage.textIndex.Num, stage.loadedTextEditor.Item(stage.proccessDecodeIndex).Str), ","))
                    {
                        stage.fileDat = stage.fileDat.Str + "ء";
                    }
                    else
                    {
                        stage.fileDat = stage.fileDat.Str + LetterOf(stage.textIndex.Num, stage.loadedTextEditor.Item(stage.proccessDecodeIndex).Str);
                    }
                    stage.textIndex = stage.textIndex.Num + 1;
                }
                stage.fileDat = stage.fileDat.Str + "|";
            }
            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
        }
        stage.fileDat = stage.fileDat.Str + ",";
        FileFindData(file);
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 50, ",", "", "");
        if (Eq(stage.fileFound, 1) && Eq(stage.decodedElements.Item(1), stage.textLoadedscript))
        {
            stage.engineFiles.Replace(stage.fileLoadIndex, stage.fileDat);
        }
        else
        {
            Message("an error occurred while saving", "_icon.warn", "Error_3", "");
        }
    }

