    /// <summary>Custom block <c>Glue3d.Execute</c> (run without screen refresh).</summary>
    void Glue3dExecute()
    {
        if (Eq(stage.allRun, 1))
        {
            stage.timeClockSpeed = 1 + stage.ramEngineData.Item(210).Num;
            stage.allClock = stage.allClock.Num + 1;
            stage.timeCpuCycle = 1;
            stage.allTime = stage.allTime.Num + stage.timeDelta.Num;
            stage.objectIndex = 2;
            for (double i1 = 0, times1 = Round(stage.scene.Item(1).Num); i1 < times1; i1++)
            {
                stage.scriptExit = 0;
                stage.scriptHeader = stage.loadedScripts.IndexOf(stage.scene.Item(stage.objectIndex.Num + 29).Str + ".start");
                stage.scriptEnd = stage.loadedScripts.IndexOf(stage.scene.Item(stage.objectIndex.Num + 29).Str + ".end");
                if (Eq(stage.scene.Item(stage.objectIndex.Num + 7), "elementui") && Eq(stage.allClock, 1))
                {
                    InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num + 3), "ui-id", "_icon.empty");
                    InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num + 3), "ui-clickable", "false");
                    InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num + 3), "ui-text", "");
                    InsertDataToObjectData(stage.scene.Item(stage.objectIndex.Num + 3), "ui-ghost", "");
                }
                for (double i2 = 0, times2 = Round((8 * (1 - stage.timeClockMode.Num) + ((stage.scriptEnd.Num - stage.scriptHeader.Num) * (stage.timeClockMode.Num * 0.8))) * (stage.timeClockSpeed.Num * 1.5)); i2 < times2; i2++)
                {
                    stage.timeScriptclock = (stage.scriptEnd.Num - stage.scriptHeader.Num - 1) * stage.timeClockSpeed.Num;
                    if (Eq(stage.scriptExit, 0) && (!(Eq(stage.scene.Item(stage.objectIndex.Num + 29), "") || Eq(stage.scene.Item(stage.objectIndex.Num + 31), "halt"))))
                    {
                        stage.terminalHeader = stage.terminal.Length + 1;
                        stage.terminalMessage = 0;
                        RunLineMainObjectScript(stage.scene.Item(stage.objectIndex.Num + 31), stage.scene.Item(stage.objectIndex.Num + 3), stage.scene.Item(stage.objectIndex.Num + 29));
                        if (Eq(stage.scriptExit, 0) && (Lt(stage.scene.Item(stage.objectIndex.Num + 35), 0.0125) && (!Eq(stage.scene.Item(stage.objectIndex.Num + 31), "halt"))))
                        {
                            stage.scene.Replace(stage.objectIndex.Num + 31, stage.scene.Item(stage.objectIndex.Num + 31).Num + 1);
                            stage.scene.Replace(stage.objectIndex.Num + 37, 0);
                        }
                    }
                }
                if (Eq(stage.scriptExit, 0))
                {
                    stage.objectIndex = stage.objectIndex.Num + stage.scene.Item(stage.objectIndex).Num;
                }
            }
            stage.timeCpuCycle = stage.timeCpuCycle.Num + 1;
        }
    }

    /// <summary>Custom block <c>Run Line (clock) main object (object) script (script)</c> (run without screen refresh).</summary>
    void RunLineMainObjectScript(Value clock, Value @object, Value script)
    {
        stage.scriptReadindex = 1 + (stage.scriptHeader.Num + clock.Num);
        stage.scriptLine = stage.loadedScripts.Item(stage.scriptReadindex);
        stage.scriptObject = @object;
        stage.scriptName = script;
        if (!((Eq(stage.scriptLine, script.Str + ".end") || Eq(stage.scriptLine, "")) || (Eq(LetterOf(2, stage.scriptLine.Str), "/") && Eq(LetterOf(1, stage.scriptLine.Str), "/"))))
        {
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.scriptLine.Str + " ", "", " (),", "", ".");
            if (Eq(stage.decodedElements.Item(1), "object"))
            {
                ProccessObject();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "model"))
            {
                ProccessModel();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "math"))
            {
                ProccessMath();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "var"))
            {
                ProccessVariable();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "physics"))
            {
                ProccessPhysics();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "game"))
            {
                ProccessGame();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "terminal"))
            {
                ProccessTerminal();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "sound"))
            {
                ProccessSound();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "interface"))
            {
                ProccessInterface();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "file"))
            {
                ProccessFile();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "time"))
            {
                ProccessTime();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "editor"))
            {
                ProccessEditor();
                return;
            }
            if (Eq(stage.decodedElements.Item(1), "list"))
            {
                ProccessList();
                return;
            }
            ProccessOther();
        }
        else
        {
            if (Eq(stage.scriptLine, script.Str + ".end"))
            {
                TerminalPrint("finished code", -35);
                stage.scene.Replace(stage.objectIndex.Num + 31, "halt");
            }
        }
    }

    /// <summary>Custom block <c>proccess.object</c> (run without screen refresh).</summary>
    void ProccessObject()
    {
        DataRecall();
        if (Eq(stage.decodedElements.Item(2), "edit_data"))
        {
            EditDataInObjectDataOperation(stage.dataVal1, stage.dataVal2, stage.dataVal3, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "distance"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "x", 0, "read");
            stage.gameX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "y", 0, "read");
            stage.gameY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "z", 0, "read");
            stage.gameZ = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "x", 0, "read");
            stage.gameFollowX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "y", 0, "read");
            stage.gameFollowY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "z", 0, "read");
            stage.gameFollowZ = stage.dataReturn;
            stage.dataVal1 = Math.Sqrt((stage.gameX.Num - stage.gameFollowX.Num) * (stage.gameX.Num - stage.gameFollowX.Num) + ((stage.gameY.Num - stage.gameFollowY.Num) * (stage.gameY.Num - stage.gameFollowY.Num) + ((stage.gameZ.Num - stage.gameFollowZ.Num) * (stage.gameZ.Num - stage.gameFollowZ.Num))));
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.dataVal1, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "get_data"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.dataVal1, stage.dataVal2, 0, "read");
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.dataReturn, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "rotate_toward"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "rx", "-", "read");
            stage.gameDirx = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "x", "-", "read");
            stage.gameDiry = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "z", "-", "read");
            stage.gameDirz = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "x", "-", "read");
            stage.gameX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "z", "-", "read");
            stage.gameY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "rx", (0 - (Atan(Nz((stage.gameDiry.Num - stage.gameX.Num) / (stage.gameDirz.Num - stage.gameY.Num))) + (180 * Num(Gt(stage.gameY, stage.gameDirz)))) - stage.gameDirx.Num) / stage.dataVal2.Num, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "turn"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "rx", stage.dataVal1, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "ry", stage.dataVal2, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "rz", stage.dataVal3, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "move_dir"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "x", Nz(Cos(stage.dataVal1.Num + 90)) * stage.dataVal2.Num, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "z", Nz(Sin(stage.dataVal1.Num + 90)) * stage.dataVal2.Num, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "move"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "x", stage.dataVal1, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "y", stage.dataVal2, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "z", stage.dataVal3, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "rotate_to"))
        {
            if (Eq(stage.dataVal4, 1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "rx", stage.dataVal1, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "ry", stage.dataVal2, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "rz", stage.dataVal3, "set");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "rx", "", "read");
                stage.tempA1 = stage.dataReturn;
                EditDataInObjectDataOperation(stage.scriptObject, "rx", (stage.dataVal1.Num - stage.dataReturn.Num) / (stage.dataVal4.Num * stage.timeClockSpeed.Num + 1), "add");
                EditDataInObjectDataOperation(stage.scriptObject, "ry", "", "read");
                stage.tempA2 = stage.dataReturn;
                EditDataInObjectDataOperation(stage.scriptObject, "ry", (stage.dataVal2.Num - stage.dataReturn.Num) / (stage.dataVal4.Num * stage.timeClockSpeed.Num + 1), "add");
