    /// <summary>Custom block <c>proccess.model</c> (run without screen refresh).</summary>
    void ProccessModel()
    {
        DataRecall();
        if (Eq(stage.decodedElements.Item(2), "set_model"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "model", stage.dataVal1, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "refresh_models"))
        {
            stage.loadedModels.DeleteAll();
            stage.loadedModels.Add(0);
            EngineRefreshRenderQueue();
        }
        if (Eq(stage.decodedElements.Item(2), "set_bone"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), 1, "", "", "");
                EngineLoad3dModelBone(stage.decodedElements.Item(1), 1, "." + stage.scriptObject.Str);
                EditDataInObjectDataOperation(stage.scriptObject, "bone", stage.dataVal1, "set");
                InsertDataToObjectData(stage.scriptObject, "bone_ease", 1);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "ease"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "bone_ease", stage.dataVal1, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "rotate_bone") || Eq(stage.decodedElements.Item(2), "turn_bone"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "bone_ease", 0, "read");
            stage.modelBoneease = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "bone", 0, "read");
            stage.engineBoneparent = stage.loadedBoneTree.IndexOf(stage.dataVal4.Str + (".b-" + (stage.dataReturn.Str + ("." + stage.scriptObject.Str)))) - 8;
            if (Eq(stage.decodedElements.Item(2), "rotate_bone"))
            {
                if (Eq(stage.modelBoneease, 0))
                {
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 4, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num + (10 * (Num(!Eq(Math.Floor(Nz(stage.dataVal1.Num / 2)), Math.Floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num / 5)))) * (1 - (Num(Lt(stage.dataVal1, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num) / 3));
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 5, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num + (10 * (Num(!Eq(Math.Floor(Nz(stage.dataVal2.Num / 5)), Math.Floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num / 5)))) * (1 - (Num(Lt(stage.dataVal2, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num) / 3));
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 6, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num + Nz((stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num + (10 * (Num(!Eq(Math.Floor(Nz(stage.dataVal3.Num / 5)), Math.Floor(Nz(stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num / 5)))) * (1 - (Num(Lt(stage.dataVal3, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6))) * 2)))) - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num) / 3));
                }
                else
                {
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 4, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num + Nz((stage.dataVal1.Num - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num) / stage.modelBoneease.Num));
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 5, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num + Nz((stage.dataVal2.Num - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num) / stage.modelBoneease.Num));
                    stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 6, stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num + Nz((stage.dataVal3.Num - stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num) / stage.modelBoneease.Num));
                }
            }
            else
            {
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 4, stage.dataVal1.Num + stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 4).Num);
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 5, stage.dataVal2.Num + stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 5).Num);
                stage.loadedBoneTree.Replace(stage.engineBoneparent.Num + 6, stage.dataVal3.Num + stage.loadedBoneTree.Item(stage.engineBoneparent.Num + 6).Num);
            }
        }
    }

