        }
        if (Eq(stage.decodedElements.Item(2), "camera_1st"))
        {
            EditDataInObjectDataOperation(stage.dataVal1, "x", "-", "read");
            stage.gameFollowX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "y", "-", "read");
            stage.gameFollowY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "z", "-", "read");
            stage.gameFollowZ = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "rx", "-", "read");
            stage.gameFollowDirx = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "ry", "-", "read");
            stage.gameFollowDiry = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "rz", "-", "read");
            stage.gameFollowDirz = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "x", stage.gameFollowX, "set");
            EditDataInObjectDataOperation(stage.scriptObject, "y", stage.gameFollowY.Num + stage.dataVal2.Num, "set");
            EditDataInObjectDataOperation(stage.scriptObject, "z", stage.gameFollowZ, "set");
            EditDataInObjectDataOperation(stage.scriptObject, "rx", stage.gameFollowDirx, "set");
            if (false)
            {
                EditDataInObjectDataOperation(stage.scriptObject, "ry", stage.gameFollowDiry, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "rz", stage.gameFollowDirz, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "camera_3rd"))
        {
            stage.gameFollowDistance = stage.dataVal2;
            EditDataInObjectDataOperation(stage.scriptObject, "x", "-", "read");
            stage.gameX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "y", "-", "read");
            stage.gameY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "z", "-", "read");
            stage.gameZ = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "rx", "-", "read");
            stage.gameDirx = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "x", "-", "read");
            stage.gameFollowX = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "y", "-", "read");
            stage.gameFollowY = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "z", "-", "read");
            stage.gameFollowZ = stage.dataReturn;
            EditDataInObjectDataOperation(stage.dataVal1, "rx", "-", "read");
            stage.gameFollowDirx = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "x", (stage.gameFollowX.Num + (stage.gameFollowDistance.Num * Nz(Cos(stage.gameFollowDirx.Num - 90))) - stage.gameX.Num) / stage.dataVal3.Num, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "y", stage.gameFollowY.Num + Nz(stage.gameFollowDistance.Num / 3), "set");
            EditDataInObjectDataOperation(stage.scriptObject, "z", (stage.gameFollowZ.Num + (stage.gameFollowDistance.Num * Nz(Sin(stage.gameFollowDirx.Num - 90))) - stage.gameZ.Num) / stage.dataVal3.Num, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "rx", (stage.gameFollowDirx.Num - stage.gameDirx.Num) / stage.dataVal3.Num, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "key_pressed"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            if (KeyPressed(stage.dataVal1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", "true", "set");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", "false", "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "fov"))
        {
            stage.engineFov = stage.dataVal1;
        }
        if (Eq(stage.decodedElements.Item(2), "get_key"))
        {
            DetectKeyGame(0, 1);
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.inputKey, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "movement"))
        {
            stage.engineRequirment = 0;
            EditDataInObjectDataOperation(stage.scriptObject, "physics", "-", "read");
            stage.engineRequirment = stage.engineRequirment.Num + (Num(!Eq(stage.dataReturn, "null")) * 1);
            EditDataInObjectDataOperation(stage.scriptObject, "game", "-", "read");
            stage.engineRequirment = stage.engineRequirment.Num + (Num(!Eq(stage.dataReturn, "null")) * 1);
            if (Eq(stage.engineRequirment, 2))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "movement_type", "-", "read");
                GameMoveplayer(stage.dataVal1, stage.dataVal2, stage.dataReturn);
            }
            else
            {
                TerminalPrint("you-need-to-include-both-\"physics\"-and-\"game\"", "");
            }
        }
    }

    /// <summary>Custom block <c>proccess.math</c> (run without screen refresh).</summary>
    void ProccessMath()
    {
        if (Contains("addءsubtractءmultiplyءdivideءmoduloءpowerءsqrtءandءorءxorءnotءgreater_thanءless_thanءequalsءrandomءjoinءletterء", stage.decodedElements.Item(2).Str + "ء"))
        {
            Operation(stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(2), stage.decodedElements.Item(6), stage.decodedElements.Item(7));
            stage.mathResult = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", stage.mathResult);
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.mathResult, "set");
            }
        }
        if (Contains("absءfloorءsinءcosءtanءatanءasinءacosءlogءnotء", stage.decodedElements.Item(2).Str + "ء"))
        {
            Operation(stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(2), "", "");
            stage.mathResult = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", stage.mathResult);
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.mathResult, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "interpolate"))
        {
            DataRecall();
            stage.mathResult = stage.dataVal2.Num - Nz((stage.dataVal2.Num - stage.dataVal1.Num) / stage.dataVal3.Num);
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", "-", "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", stage.mathResult);
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.mathResult, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "clamp"))
        {
            DataRecall();
            stage.mathResult = stage.dataVal1;
            if (Lt(stage.dataVal1, stage.dataVal2))
            {
                stage.mathResult = stage.dataVal2;
            }
            else
            {
                if (Gt(stage.dataVal1, stage.dataVal3))
                {
                    stage.mathResult = stage.dataVal3;
                }
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", stage.mathResult);
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.mathResult, "set");
            }
        }
    }

