    /// <summary>Custom block <c>proccess: other</c> (run without screen refresh).</summary>
    void ProccessOther()
    {
        if (Eq(stage.decodedElements.Item(1), "wait"))
        {
            if (Eq(stage.scene.Item(stage.objectIndex.Num + 37), 0))
            {
                if (Eq(stage.decodedElements.Item(3), "var"))
                {
                    EditDataInObjectDataOperation(stage.scriptObject, stage.decodedElements.Item(4), 0, "read");
                    stage.dataVal1 = stage.dataReturn;
                }
                else
                {
                    stage.dataVal1 = stage.decodedElements.Item(4);
                }
                stage.scene.Replace(stage.objectIndex.Num + 35, stage.dataVal1);
                stage.scene.Replace(stage.objectIndex.Num + 37, "clock_delta");
            }
            if (Eq(stage.scene.Item(stage.objectIndex.Num + 37), "clock_delta"))
            {
                stage.scene.Replace(stage.objectIndex.Num + 35, stage.scene.Item(stage.objectIndex.Num + 35).Num - Nz(stage.timeDelta.Num / stage.timeScriptclock.Num));
            }
            return;
        }
        if (Eq(stage.decodedElements.Item(1), "forever"))
        {
            if (!stage.programloops.Contains(stage.scriptObject))
            {
                stage.programloops.Add(stage.scriptObject);
                stage.programloops.Add(0);
            }
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject);
            stage.programloops.Replace(stage.scriptLoopindex.Num + 1, stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num + 1);
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject) + ((stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num - 1) * 2);
            stage.programloops.Insert(stage.scriptLoopindex.Num + 2, stage.scene.Item(stage.objectIndex.Num + 31).Num + 1);
            stage.programloops.Insert(stage.scriptLoopindex.Num + 3, "true");
            return;
        }
        if (Eq(stage.decodedElements.Item(1), "endforever"))
        {
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject);
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject) + ((stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num - 1) * 2);
            stage.scene.Replace(stage.objectIndex.Num + 31, stage.programloops.Item(stage.scriptLoopindex.Num + 2).Num - 1);
            return;
        }
        if (Eq(stage.decodedElements.Item(1), "while"))
        {
            if (!stage.programloops.Contains(stage.scriptObject))
            {
                stage.programloops.Add(stage.scriptObject);
                stage.programloops.Add(0);
            }
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject);
            stage.programloops.Replace(stage.scriptLoopindex.Num + 1, stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num + 1);
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject) + ((stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num - 1) * 2);
            stage.programloops.Insert(stage.scriptLoopindex.Num + 2, stage.scene.Item(stage.objectIndex.Num + 31).Num + 1);
            stage.dataResult = "";
            stage.dataIndex = 3;
            for (double i1 = 0, times1 = Round(stage.decodedElements.Length - 3); i1 < times1; i1++)
            {
                stage.dataResult = stage.dataResult.Str + (stage.decodedElements.Item(stage.dataIndex).Str + " ");
                stage.dataIndex = stage.dataIndex.Num + 1;
            }
            stage.programloops.Insert(stage.scriptLoopindex.Num + 3, stage.dataResult);
            return;
        }
        if (Eq(stage.decodedElements.Item(1), "endwhile"))
        {
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject);
            stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject) + ((stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num - 1) * 2);
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.programloops.Item(stage.scriptLoopindex.Num + 3), "", " ", "", "");
            Operation(stage.decodedElements.Item(1), stage.decodedElements.Item(2), stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(5));
            if (Eq(stage.dataReturn, "true"))
            {
                stage.scene.Replace(stage.objectIndex.Num + 31, stage.programloops.Item(stage.scriptLoopindex.Num + 2).Num - 1);
            }
            else
            {
                if (Eq(stage.dataReturn, "false"))
                {
                    stage.programloops.Delete(stage.scriptLoopindex.Num + 3);
                    stage.programloops.Delete(stage.scriptLoopindex.Num + 2);
                    stage.scriptLoopindex = stage.programloops.IndexOf(stage.scriptObject);
                    stage.programloops.Replace(stage.scriptLoopindex.Num + 1, stage.programloops.Item(stage.scriptLoopindex.Num + 1).Num - 1);
                }
                else
                {
                    if (Eq(stage.dataReturn, "null"))
                    {
                        TerminalPrint("error: null operation in while loop", "");
                    }
                }
            }
            return;
        }
        if (Eq(stage.decodedElements.Item(1), "if"))
        {
            stage.dataResult = "";
            stage.dataIndex = 3;
            for (double i1 = 0, times1 = Round(stage.decodedElements.Length - 3); i1 < times1; i1++)
            {
                stage.dataResult = stage.dataResult.Str + (stage.decodedElements.Item(stage.dataIndex).Str + " ");
                stage.dataIndex = stage.dataIndex.Num + 1;
            }
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.dataResult, "", " ", "", "");
            Operation(stage.decodedElements.Item(1), stage.decodedElements.Item(2), stage.decodedElements.Item(3), stage.decodedElements.Item(4), stage.decodedElements.Item(5));
            if (Eq(stage.dataReturn, "false"))
            {
                stage.textIndex2 = 1 + (stage.loadedScripts.IndexOf(stage.scriptName.Str + ".start") + stage.scene.Item(stage.objectIndex.Num + 31).Num);
                stage.scriptIfs = 1;
                while (!Eq(stage.scriptIfs, 0))
                {
                    stage.textIndex2 = stage.textIndex2.Num + 1;
                    stage.scriptLine2 = stage.loadedScripts.Item(stage.textIndex2);
                    if (Eq(stage.loadedScripts.Item(stage.textIndex2.Num - 1), stage.scriptName.Str + ".end"))
                    {
                        TerminalPrint("error: no end was found!", "");
                        return;
                    }
                    DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.scriptLine2.Str + " ", 1, " .()", "", "");
                    if (Eq(stage.decodedElements.Item(1), "if"))
                    {
                        stage.scriptIfs = stage.scriptIfs.Num + 1;
                    }
                    if (Eq(stage.decodedElements.Item(1), "endif"))
                    {
                        stage.scriptIfs = stage.scriptIfs.Num + -1;
                    }
                }
                stage.scene.Replace(stage.objectIndex.Num + 31, stage.textIndex2.Num - (stage.loadedScripts.IndexOf(stage.scriptName.Str + ".start") + 0) - 2);
            }
        }
    }

