    /// <summary>Custom block <c>Load Script to editor (script)</c> (run without screen refresh).</summary>
    void LoadScriptToEditor(Value script)
    {
        stage.loadedTextEditor.DeleteAll();
        FileFindData(script);
        DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), "", "", "", "");
        stage.fileDat = stage.decodedElements.Item(2);
        stage.proccessDecode = "";
        stage.proccessDecodeIndex = 1;
        for (double i1 = 0, times1 = Round(stage.fileDat.Str.Length); i1 < times1; i1++)
        {
            if (Eq(LetterOf(stage.proccessDecodeIndex.Num, stage.fileDat.Str), "ء"))
            {
                stage.proccessDecode = stage.proccessDecode.Str + ",";
            }
            else
            {
                stage.proccessDecode = stage.proccessDecode.Str + LetterOf(stage.proccessDecodeIndex.Num, stage.fileDat.Str);
            }
            if (Eq(stage.proccessDecode, "\\n"))
            {
                stage.loadedTextEditor.Add("");
                stage.proccessDecode = "";
                stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
            }
            else
            {
                if (Eq(LetterOf(stage.proccessDecodeIndex.Num + 1, stage.fileDat.Str), "|"))
                {
                    stage.loadedTextEditor.Add(stage.proccessDecode);
                    stage.proccessDecode = "";
                    stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
                }
            }
            stage.proccessDecodeIndex = stage.proccessDecodeIndex.Num + 1;
        }
    }

    /// <summary>Custom block <c>Find intersection between point a-b with seg2dmap (ax) (az) - (bx) (bz) y: (y) special (s) nogroup (nogroup)</c> (run without screen refresh).</summary>
    void FindIntersectionBetweenPointABWithSeg2dmapYSpecialNogroup(Value ax, Value az, Value bx, Value bz, Value y, Value s, Value nogroup)
    {
        stage.engineIndex = 1;
        stage.engineGlobalinteresction = 0;
        stage.tempGroup.DeleteAll();
        stage.tempSort.DeleteAll();
        stage.tempY2.DeleteAll();
        stage.tempY1.DeleteAll();
        stage.tempX2.DeleteAll();
        stage.tempZ2.DeleteAll();
        stage.temp.DeleteAll();
        stage.tempGroup.Add("A");
        stage.tempSort.Add("A");
        stage.tempY1.Add("A");
        stage.tempY2.Add("A");
        stage.temp.Add("A");
        stage.tempX2.Add("A");
        stage.tempZ2.Add("A");
        SetPenSize(1);
        for (double i1 = 0, times1 = Round(Nz((stage.loadedPolygonMap.Length - 1) / stage.enginePolygonattributes.Num) + 0); i1 < times1; i1++)
        {
            _2dsegIntersect(ax, az, bx, bz, stage.loadedPolygonMap.Item(stage.engineIndex.Num + 1), stage.loadedPolygonMap.Item(stage.engineIndex.Num + 2), stage.loadedPolygonMap.Item(stage.engineIndex.Num + 3), stage.loadedPolygonMap.Item(stage.engineIndex.Num + 4));
            if (Eq(stage.engineIntersect, 1))
            {
                if (Eq(s, 1))
                {
                    if ((!Eq(stage.loadedPolygonMap.Item(stage.engineIndex.Num + 9), "ghost")) && (Gt(stage.loadedPolygonMap.Item(stage.engineIndex.Num + 12), 0) || Eq(nogroup, 1)))
                    {
                        stage.engineIntersectwallx = ax.Num + (stage.engineA.Num * (bx.Num - ax.Num));
                        stage.engineIntersectwallz = az.Num + (stage.engineA.Num * (bz.Num - az.Num));
                        stage.engineIntersectwally1 = stage.loadedPolygonMap.Item(stage.engineIndex.Num + 5).Num + ((stage.loadedPolygonMap.Item(stage.engineIndex.Num + 6).Num - stage.loadedPolygonMap.Item(stage.engineIndex.Num + 5).Num) * stage.engineB.Num);
                        stage.engineIntersectwally2 = stage.loadedPolygonMap.Item(stage.engineIndex.Num + 7).Num + ((stage.loadedPolygonMap.Item(stage.engineIndex.Num + 8).Num - stage.loadedPolygonMap.Item(stage.engineIndex.Num + 7).Num) * stage.engineB.Num);
                        stage.engineIntersectdistance = Math.Sqrt(((y.Num - stage.engineIntersectwally1.Num) * 1) * ((y.Num - stage.engineIntersectwally1.Num) * 1) + ((ax.Num - stage.engineIntersectwallx.Num) * (ax.Num - stage.engineIntersectwallx.Num)) + ((az.Num - stage.engineIntersectwallz.Num) * (az.Num - stage.engineIntersectwallz.Num)));
                        Sort(stage.engineIntersectdistance);
                        stage.tempGroup.Insert(stage.sortIndex.Num + 1, stage.loadedPolygonMap.Item(stage.engineIndex.Num + 12));
                        stage.tempY1.Insert(stage.sortIndex.Num + 1, stage.engineIntersectwally1);
                        stage.tempY2.Insert(stage.sortIndex.Num + 1, stage.engineIntersectwally2);
                        stage.temp.Insert(stage.sortIndex.Num + 1, stage.engineIndex);
                        stage.tempX2.Insert(stage.sortIndex.Num + 1, stage.engineIntersectwallx);
                        stage.tempZ2.Insert(stage.sortIndex.Num + 1, stage.engineIntersectwallz);
                        stage.engineGlobalinteresction = 1;
                    }
                }
                else
                {
                    Sort(stage.engineA.Num * 100000 + Math.Abs(y.Num - (stage.loadedPolygonMap.Item(stage.engineIndex.Num + 5).Num + ((stage.loadedPolygonMap.Item(stage.engineIndex.Num + 6).Num - stage.loadedPolygonMap.Item(stage.engineIndex.Num + 5).Num) * stage.engineB.Num))));
                    stage.temp.Insert(stage.sortIndex.Num + 1, stage.engineIndex);
                    stage.engineGlobalinteresction = 1;
                }
            }
            stage.engineIndex = stage.engineIndex.Num + stage.enginePolygonattributes.Num;
        }
        stage.tempGroup.Delete(1);
        stage.tempSort.Delete(1);
        stage.temp.Delete(1);
        stage.tempY1.Delete(1);
        stage.tempY2.Delete(1);
        stage.tempX2.Delete(1);
        stage.tempZ2.Delete(1);
        if (Eq(stage.temp.Length, 0))
        {
            stage.engineHitscan = "";
            stage.engineIntersectwallx = 0;
            stage.engineIntersectwallz = 0;
            stage.engineIntersectwallgroup = 0;
            stage.engineIntersectdistance = 0;
        }
        else
        {
            stage.engineHitscan = stage.temp.Item(stage.temp.Length);
            if (Eq(s, 1))
            {
                stage.engineIntersectwally1 = stage.tempY1.Item(stage.temp.Length);
                stage.engineIntersectwally2 = stage.tempY2.Item(stage.temp.Length);
                stage.engineIntersectwallx = stage.tempX2.Item(stage.temp.Length);
                stage.engineIntersectwallz = stage.tempZ2.Item(stage.temp.Length);
                stage.engineIntersectwallgroup = stage.tempGroup.Item(stage.tempGroup.Length);
                stage.engineIntersectdistance = Math.Sqrt((ax.Num - stage.engineIntersectwallx.Num) * (ax.Num - stage.engineIntersectwallx.Num) + ((az.Num - stage.engineIntersectwallz.Num) * (az.Num - stage.engineIntersectwallz.Num)));
            }
        }
    }

