    /// <summary>Custom block <c>operation (type1) (data1)   (op)   (type2) (data2)</c> (run without screen refresh).</summary>
    void Operation(Value type1, Value data1, Value op, Value type2, Value data2)
    {
        stage.dataReturn = "null";
        if (Eq(type1, "var"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, data1, 0, "read");
            stage.dataVal1 = stage.dataReturn;
        }
        else
        {
            stage.dataVal1 = data1;
        }
        if (Eq(type2, "var"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, data2, 0, "read");
            stage.dataVal2 = stage.dataReturn;
        }
        else
        {
            stage.dataVal2 = data2;
        }
        if (Contains("<ر>ر=رandرorرxorرnandرnorرgreater_thanرless_thanرequalsر", op.Str + "ر"))
        {
            stage.dataReturn = "false";
            if ((Eq(op, "=") || Eq(op, "equals")) && Eq(stage.dataVal1, stage.dataVal2))
            {
                stage.dataReturn = "true";
                return;
            }
            if ((Eq(op, ">") || Eq(op, "greater_than")) && Gt(stage.dataVal1, stage.dataVal2))
            {
                stage.dataReturn = "true";
                return;
            }
            if ((Eq(op, "<") || Eq(op, "less_than")) && Lt(stage.dataVal1, stage.dataVal2))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "and") && (Eq(stage.dataVal1, "true") && Eq(stage.dataVal2, "true")))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "or") && (Eq(stage.dataVal1, "true") || Eq(stage.dataVal2, "true")))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "xor") && ((Eq(stage.dataVal1, "true") || Eq(stage.dataVal2, "true")) && (!(Eq(stage.dataVal1, "true") && Eq(stage.dataVal2, "true")))))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "nand") && (!(Eq(stage.dataVal1, "true") && Eq(stage.dataVal2, "true"))))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "nor") && (!(Eq(stage.dataVal1, "true") || Eq(stage.dataVal2, "true"))))
            {
                stage.dataReturn = "true";
                return;
            }
            if (Eq(op, "not") && Eq(stage.dataVal1, "false"))
            {
                stage.dataReturn = "true";
                return;
            }
        }
        else
        {
            if (Eq(op, "add"))
            {
                stage.dataReturn = stage.dataVal1.Num + stage.dataVal2.Num;
                return;
            }
            if (Eq(op, "subtract"))
            {
                stage.dataReturn = stage.dataVal1.Num - stage.dataVal2.Num;
                return;
            }
            if (Eq(op, "multiply"))
            {
                stage.dataReturn = stage.dataVal1.Num * stage.dataVal2.Num;
                return;
            }
            if (Eq(op, "divide"))
            {
                stage.dataReturn = stage.dataVal1.Num / stage.dataVal2.Num;
                return;
            }
            if (Eq(op, "modulo"))
            {
                stage.dataReturn = Mod(stage.dataVal1.Num, stage.dataVal2.Num);
                return;
            }
            if (Eq(op, "power"))
            {
                stage.dataVal3 = stage.dataVal1;
                for (double i1 = 0, times1 = Round(stage.dataVal2.Num - 1); i1 < times1; i1++)
                {
                    stage.dataVal1 = stage.dataVal1.Num * stage.dataVal3.Num;
                }
                stage.dataReturn = stage.dataVal1;
                return;
            }
            if (Eq(op, "sqrt"))
            {
                stage.dataReturn = Math.Sqrt(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "sin"))
            {
                stage.dataReturn = Sin(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "cos"))
            {
                stage.dataReturn = Cos(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "tan"))
            {
                stage.dataReturn = Tan(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "log"))
            {
                stage.dataReturn = Log10(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "asin"))
            {
                stage.dataReturn = Asin(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "acos"))
            {
                stage.dataReturn = Acos(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "atan"))
            {
                stage.dataReturn = Atan(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "abs"))
            {
                stage.dataReturn = Math.Abs(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "floor"))
            {
                stage.dataReturn = Math.Floor(stage.dataVal1.Num);
                return;
            }
            if (Eq(op, "random"))
            {
                stage.dataReturn = PickRandom(stage.dataVal1, stage.dataVal2);
                return;
            }
            if (Eq(op, "join"))
            {
                stage.dataReturn = stage.dataVal1.Str + stage.dataVal2.Str;
                return;
            }
            if (Eq(op, "letter"))
            {
                stage.dataReturn = LetterOf(stage.dataVal1.Num, stage.dataVal2.Str);
                return;
            }
        }
    }

    /// <summary>Custom block <c>block based editor</c> (run without screen refresh).</summary>
    void BlockBasedEditor()
    {
        stage.textZoomgesture = stage.textZoomgesture.Num * 0.8;
        stage.textZoom = stage.textZoomgesture.Num + 1;
        stage.guiScrollbar = stage.loadedTextEditor.Length / 50;
        stage.renderTextY = 1;
        ClearEffects();
        stage.textOffsety = 0;
        stage.textIndent = 0;
        if (Gt(stage.loadedTextEditor.Length, 0))
        {
            stage.textDraglocation = stage.loadedTextEditor.Length;
        }
        else
        {
            stage.textDraglocation = 1;
        }
        for (double i1 = 0, times1 = Round(stage.loadedTextEditor.Length); i1 < times1; i1++)
        {
            stage.editorBlocky = ((stage.renderTextY.Num - stage.textOffsety.Num - 1) * -20 + 97 + ((stage.ramEngineData.Item(174).Num * stage.guiScrollbar.Num) * 10)) / stage.textZoom.Num;
            if ((KeyPressed("c") || (!Eq(stage.textSelectedline, stage.renderTextY))) && (!Eq(stage.loadedTextEditor.Item(stage.renderTextY), "")))
            {
                stage.temp.DeleteAll();
                DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.loadedTextEditor.Item(stage.renderTextY).Str + " ", "", ". ,()", "", "");
                stage.textIndex = 1;
                for (double i2 = 0, times2 = Round(stage.decodedElements.Length); i2 < times2; i2++)
                {
                    stage.temp.Add(stage.decodedElements.Item(stage.textIndex));
                    stage.textIndex = stage.textIndex.Num + 1;
                }
                DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.loadedTextEditor.Item(stage.renderTextY).Str + " ", "", " ,()", 1, ".");
                if ((!Eq(stage.textIndent, 0)) && (Eq(stage.decodedElements.Item(1), "endforever ") || (Eq(stage.decodedElements.Item(1), "endif ") || Eq(stage.decodedElements.Item(1), "endwhile "))))
                {
                    stage.textIndent = stage.textIndent.Num + -1;
                }
                BlockRenderblock();
                stage.renderTextX = 0;
                stage.textAccumulativeWordIndex = 0;
                for (double i2 = 0, times2 = Round(stage.decodedElements.Length); i2 < times2; i2++)
                {
                    stage.textAccumulativeWordIndex = stage.textAccumulativeWordIndex.Num + stage.decodedElements.Item(stage.renderTextX).Str.Length;
                    stage.renderTextX = stage.renderTextX.Num + 1;
                    BlockRenderinput();
                    stage.textX = 1;
                    for (double i3 = 0, times3 = Round(stage.decodedElements.Item(stage.renderTextX).Str.Length); i3 < times3; i3++)
                    {
                        if (Lt(Math.Abs(stage.editorBlocky.Num + -3), 160))
                        {
                            if (Contains(stage.temp.Item(1).Str, "//"))
                            {
                                SetEffect(Effect.Brightness, 60);
                                SetEffect(Effect.Color, double.NegativeInfinity);
                            }
                            else
                            {
                                stage.textColorindex = Num(Eq(stage.temp.Item(stage.renderTextX).Num + 1, 1)) * stage.textColoration.IndexOf(stage.temp.Item(stage.renderTextX));
                                if (Gt(stage.textColorindex, 0))
                                {
                                    SetEffect(Effect.Brightness, stage.textColoration.Item(stage.textColorindex.Num + 1).Num);
                                    SetEffect(Effect.Color, stage.textColoration.Item(stage.textColorindex.Num + 2).Num);
                                }
                                else
                                {
                                    SetEffect(Effect.Brightness, -100);
                                }
                            }
                            stage.textCharecter = LetterOf(stage.textX.Num, stage.decodedElements.Item(stage.renderTextX).Str);
                            if (!Contains(" ,()", stage.textCharecter.Str))
                            {
                                SwitchCostume("_font.default." + stage.textCharecter.Str);
                                GoTo(Nz(((stage.textX.Num + stage.textAccumulativeWordIndex.Num - 1) * 5 - (stage.textIndent.Num * -19 + 202 + (stage.ramEngineData.Item(176).Num * 5))) / stage.textZoom.Num), stage.editorBlocky.Num);
                                SetSize(Nz((50 + (Num(Eq(stage.textBlockinput, 1)) * -15)) / stage.textZoom.Num));
                                ChangeEffect(Effect.Brightness, -25);
                                Stamp();
                                SetEffect(Effect.Brightness, -100);
                                SetEffect(Effect.Ghost, 30);
                                ChangeY(Nz(-0.5 / stage.textZoom.Num));
                                Stamp();
                            }
                            ChangeY(Nz(-0.5 / stage.textZoom.Num));
                        }
                        stage.textX = stage.textX.Num + 1;
                    }
                }
                if (Eq(stage.decodedElements.Item(1), "forever ") || (Eq(stage.decodedElements.Item(1), "while ") || Eq(stage.decodedElements.Item(1), "if ")))
                {
                    stage.textIndent = stage.textIndent.Num + 1;
                }
                if (((Eq(stage.dragId, "") && (MouseDown && Lt(Math.Abs(MouseY), 108))) && Eq(stage.textSelected, 1)) && Eq(stage.textDrag, 0))
                {
                    if (Gt(stage.textDragtimer, 0.05) && Eq(stage.guiDropdown, 0))
                    {
                        StartSound("Windows Vista Beta Blip 2");
                        stage.textSelectedtext = stage.loadedTextEditor.Item(stage.renderTextY);
                        stage.textSelectedbrightness = stage.textBrightness;
                        stage.textSelectedcolor = stage.textColor;
                        stage.textSelectedline = stage.renderTextY;
                        stage.textDrag = 1;
                        stage.textSelecttype = 1;
                    }
                    else
                    {
                        stage.textDragtimer = stage.textDragtimer.Num + stage.timeDelta.Num;
                    }
                }
            }
            else
            {
                stage.textOffsety = stage.textOffsety.Num + 1;
            }
            stage.renderTextY = stage.renderTextY.Num + 1;
        }
        if (!MouseDown)
