    void GameMoveplayer(Value speed, Value turnSpeed, Value type)
    {
        if (Eq(type, "human"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "rx", "-", "read");
            stage.gameFollowDirx = stage.dataReturn.Num + 90;
            EditDataInObjectDataOperation(stage.scriptObject, "velx", (Nz(Cos(stage.gameFollowDirx.Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * Nz((speed.Num * (10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "velz", (Nz(Sin(stage.gameFollowDirx.Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * Nz((speed.Num * (10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "velx", (Nz(Cos(stage.gameFollowDirx.Num + 90)) * (Num(KeyPressed("d")) - Num(KeyPressed("a")))) * Nz((speed.Num * (-10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "velz", (Nz(Sin(stage.gameFollowDirx.Num + 90)) * (Num(KeyPressed("d")) - Num(KeyPressed("a")))) * Nz((speed.Num * (-10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "rx", (Num(KeyPressed("right arrow")) - Num(KeyPressed("left arrow"))) * Nz((turnSpeed.Num * (-60 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "stand", "-", "read");
            if (KeyPressed("space") && Eq(stage.dataReturn, 1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "stand", 0, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "jumpheight", "-", "read");
                EditDataInObjectDataOperation(stage.scriptObject, "vely", stage.dataReturn, "set");
            }
        }
        if (Eq(type, "vehicle"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "rx", "-", "read");
            stage.gameFollowDirx = stage.dataReturn.Num + 90;
            EditDataInObjectDataOperation(stage.scriptObject, "velx", (Nz(Cos(stage.gameFollowDirx.Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * Nz((speed.Num * (10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "velz", (Nz(Sin(stage.gameFollowDirx.Num)) * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * Nz((speed.Num * (10 * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
            EditDataInObjectDataOperation(stage.scriptObject, "friction", "-", "read");
            EditDataInObjectDataOperation(stage.scriptObject, "velx", stage.dataReturn, "mul");
            EditDataInObjectDataOperation(stage.scriptObject, "x", stage.dataReturn, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "friction", "-", "read");
            EditDataInObjectDataOperation(stage.scriptObject, "velz", stage.dataReturn, "mul");
            EditDataInObjectDataOperation(stage.scriptObject, "z", stage.dataReturn, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "rx", (Num(KeyPressed("d")) - Num(KeyPressed("a")) - Num(KeyPressed("left arrow"))) * Nz((turnSpeed.Num * ((-60 * (Num(KeyPressed("w")) - Num(KeyPressed("s")))) * stage.timeDelta.Num)) / stage.timeClockSpeed.Num), "add");
        }
    }

    /// <summary>Custom block <c>engine.objectphysics</c> (run without screen refresh).</summary>
    void EngineObjectphysics()
    {
        EditDataInObjectDataOperation(stage.scriptObject, "gravity", 0, "read");
        EditDataInObjectDataOperation(stage.scriptObject, "vely", (stage.dataReturn.Num * -0.3) / (stage.timeClockSpeed.Num * 5), "add");
        EditDataInObjectDataOperation(stage.scriptObject, "y", (stage.dataReturn.Num * (10 * stage.timeDelta.Num)) / (stage.timeClockSpeed.Num * 5), "add");
        stage.physicsY = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, "vertical_col", "-", "read");
        if (Eq(stage.dataReturn, "true"))
        {
            ObjectFindcollisionSurface(stage.scriptObject);
        }
        else
        {
            stage.engineSurfaceintersect = 0;
        }
        if (Lt(stage.physicsY, 0) || Eq(stage.engineSurfaceintersect, 1))
        {
            if (Eq(stage.engineSurfaceintersect, 0))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "y", 0, "set");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "y", stage.engineSurfacey1.Num - 0.00125, "set");
            }
            EditDataInObjectDataOperation(stage.scriptObject, "bounce", "-", "read");
            stage.physicsBounce = stage.dataReturn;
            EditDataInObjectDataOperation(stage.scriptObject, "vely", "-", "read");
            EditDataInObjectDataOperation(stage.scriptObject, "vely", stage.dataReturn.Num * (0 - stage.physicsBounce.Num), "set");
            EditDataInObjectDataOperation(stage.scriptObject, "stand", 1, "set");
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, "stand", 0, "set");
        }
        EditDataInObjectDataOperation(stage.scriptObject, "friction", "-", "read");
        EditDataInObjectDataOperation(stage.scriptObject, "velx", stage.dataReturn, "mul");
        stage.physicsVelx = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, "friction", "-", "read");
        EditDataInObjectDataOperation(stage.scriptObject, "velz", stage.dataReturn, "mul");
        stage.physicsVelz = stage.dataReturn;
        EditDataInObjectDataOperation(stage.scriptObject, "horizontal_col", "-", "read");
        if (Eq(stage.dataReturn, "true"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "hitwall", 0, "set");
            EditDataInObjectDataOperation(stage.scriptObject, "x", stage.physicsVelx.Num * 0.5, "add");
            ObjectFindcollisionHitbox(stage.scriptObject);
            if (Eq(stage.engineHitboxintersect, 1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "x", -1 * stage.physicsVelx.Num, "add");
                EditDataInObjectDataOperation(stage.scriptObject, "velx", 0.25, "mul");
                EditDataInObjectDataOperation(stage.scriptObject, "hitwall", 1, "set");
            }
            EditDataInObjectDataOperation(stage.scriptObject, "z", stage.physicsVelz.Num * 0.5, "add");
            ObjectFindcollisionHitbox(stage.scriptObject);
            if (Eq(stage.engineHitboxintersect, 1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "z", -1 * stage.physicsVelz.Num, "add");
                EditDataInObjectDataOperation(stage.scriptObject, "velz", 0.25, "mul");
                EditDataInObjectDataOperation(stage.scriptObject, "hitwall", 1, "set");
            }
        }
        else
        {
            EditDataInObjectDataOperation(stage.scriptObject, "x", stage.physicsVelx, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "z", stage.physicsVelz, "add");
            stage.engineHitboxintersect = 0;
        }
    }

