                    else
                    {
                        stage.textColorindex = Num(Eq(stage.temp.Item(stage.renderTextX).Num + 1, 1)) * stage.textColoration.IndexOf(stage.temp.Item(stage.renderTextX));
                        if (Gt(stage.textColorindex, 0))
                        {
                            SetEffect(Effect.Brightness, stage.textColoration.Item(stage.textColorindex.Num + 1).Num);
                            SetEffect(Effect.Color, stage.textColoration.Item(stage.textColorindex.Num + 2).Num);
