                    {
                        SwitchCostume("_font.default." + LetterOf(stage.textX.Num, stage.decodedElements.Item(stage.renderTextX).Str));
                        GoTo((stage.textX.Num + stage.textAccumulativeWordIndex.Num - 1) * 5 - (200 + (stage.ramEngineData.Item(176).Num * 5)), (stage.renderTextY.Num - 1) * -10 + 95 + ((stage.ramEngineData.Item(174).Num * stage.guiScrollbar.Num) * 10));
                        SetSize(40);
                        Stamp();
                    }
                    stage.textX = stage.textX.Num + 1;
                }
                stage.textAccumulativeWordIndex = stage.textAccumulativeWordIndex.Num + stage.decodedElements.Item(stage.renderTextX).Str.Length;
                stage.renderTextX = stage.renderTextX.Num + 1;
            }
            stage.renderTextY = stage.renderTextY.Num + 1;
        }
        GoTo(stage.textCursorx.Num * 5 - (203 + (stage.ramEngineData.Item(176).Num * 5)), stage.textCursory.Num * -10 + 95 + ((stage.ramEngineData.Item(174).Num * stage.guiScrollbar.Num) * 10));
        SwitchCostume("_font.default.|");
        SetEffect(Effect.Ghost, Math.Floor(Nz(Mod(stage.timeTimer.Num * 3, 2))) * 50);
        Stamp();
