            if (Eq(stage.textAutocomplete, "main"))
            {
                AutocompleteMain();
            }
            else
            {
                AutocompleteSection(stage.textAutocomplete);
            }
        }
    }

    /// <summary>Custom block <c>object.findcollision (surface) (object)</c> (run without screen refresh).</summary>
    void ObjectFindcollisionSurface(Value @object)
    {
        if (Eq(stage.engineSeg2D, 1))
        {
            Object2dsegSurface(@object);
            stage.tempTemp1 = stage.engineSurfaceintersect;
            stage.tempTemp2 = stage.engineSurfacey1;
        }
        else
        {
            stage.tempTemp1 = 0;
            stage.tempTemp2 = 0;
        }
        if (Eq(stage.engineTile2D, 1))
        {
            Object2dtileSurface(@object);
        }
        stage.engineSurfaceintersect = Num(Eq(stage.engineSurfaceintersect, 1) || Eq(stage.tempTemp1, 1)) * 1;
        if (Eq(stage.engineSurfaceintersect, 1) && Eq(stage.tempTemp1, 1))
        {
            stage.engineSurfacey1 = stage.tempTemp2;
        }
    }

    /// <summary>Custom block <c>object.findcollision (hitbox) (object)</c> (run without screen refresh).</summary>
    void ObjectFindcollisionHitbox(Value @object)
    {
        if (Eq(stage.engineSeg2D, 1))
        {
            Object2dsegCollision(@object);
            stage.tempTemp1 = stage.engineHitboxintersect;
        }
        else
        {
            stage.tempTemp1 = 0;
        }
        if (Eq(stage.engineTile2D, 1))
        {
            Object2dtileCollision(@object);
        }
        stage.engineHitboxintersect = Num(Eq(stage.engineHitboxintersect, 1) || Eq(stage.tempTemp1, 1)) * 1;
    }

    /// <summary>Custom block <c>2dseg.intersect (x1) (y1) - (x2) (y2) ~ (x3) (y3) - (x4) (y4)</c> (run without screen refresh).</summary>
    void _2dsegIntersect(Value x1, Value y1, Value x2, Value y2, Value x3, Value y3, Value x4, Value y4)
    {
        stage.engineA = ((x4.Num - x3.Num) * (y3.Num - y1.Num) - ((y4.Num - y3.Num) * (x3.Num - x1.Num))) / ((x4.Num - x3.Num) * (y2.Num - y1.Num) - ((y4.Num - y3.Num) * (x2.Num - x1.Num)));
        stage.engineB = ((x2.Num - x1.Num) * (y3.Num - y1.Num) - ((y2.Num - y1.Num) * (x3.Num - x1.Num))) / ((x4.Num - x3.Num) * (y2.Num - y1.Num) - ((y4.Num - y3.Num) * (x2.Num - x1.Num)));
        stage.engineIntersect = Num(Lt(Math.Abs(stage.engineA.Num - 0.5), 0.5) && Lt(Math.Abs(stage.engineB.Num - 0.5), 0.5)) * 1;
    }

