    /// <summary>Custom block <c>proccess.physics</c> (run without screen refresh).</summary>
    void ProccessPhysics()
    {
        DataRecall();
        if (Eq(stage.decodedElements.Item(2), "dir_force"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "velx", Nz(Cos(stage.dataVal1.Num + 90)) * stage.dataVal2.Num, "add");
            EditDataInObjectDataOperation(stage.scriptObject, "velz", Nz(Sin(stage.dataVal1.Num + 90)) * stage.dataVal2.Num, "add");
        }
        if (Eq(stage.decodedElements.Item(2), "include_physics"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "physics", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "physics", 0);
                InsertDataToObjectData(stage.scriptObject, "velx", 0);
                InsertDataToObjectData(stage.scriptObject, "vely", 0);
                InsertDataToObjectData(stage.scriptObject, "velz", 0);
                InsertDataToObjectData(stage.scriptObject, "gravity", 0.9);
                InsertDataToObjectData(stage.scriptObject, "jumpheight", 1.5);
                InsertDataToObjectData(stage.scriptObject, "friction", 0.85);
                InsertDataToObjectData(stage.scriptObject, "bounce", 0.1);
                InsertDataToObjectData(stage.scriptObject, "stand", 1);
                InsertDataToObjectData(stage.scriptObject, "hitwall", 1);
                InsertDataToObjectData(stage.scriptObject, "horizontal_col", "true");
                InsertDataToObjectData(stage.scriptObject, "vertical_col", "true");
                InsertDataToObjectData(stage.scriptObject, "hitbox_x", 1);
                InsertDataToObjectData(stage.scriptObject, "hitbox_y", 1);
                InsertDataToObjectData(stage.scriptObject, "hitbox_z", 1);
                InsertDataToObjectData(stage.scriptObject, "prev_sector", 0);
                InsertDataToObjectData(stage.scriptObject, "prev_y", 0);
            }
            else
            {
                TerminalPrint("physics already included!", "");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "hitbox"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "physics", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                TerminalPrint("physics not included!", "");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "hitbox_x", stage.dataVal1, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "hitbox_y", stage.dataVal2, "set");
                EditDataInObjectDataOperation(stage.scriptObject, "hitbox_z", stage.dataVal3, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "hitbox_collision"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "physics", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                TerminalPrint("physics not included!", "");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "horizontal_col", stage.dataVal1, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "surface_collision"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "physics", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                TerminalPrint("physics not included!", "");
            }
            else
            {
                EditDataInObjectDataOperation(stage.scriptObject, "vertical_col", stage.dataVal1, "set");
            }
        }
        if (Eq(stage.decodedElements.Item(2), "set_factors"))
        {
