    /// <summary>Custom block <c>Render Bone Tree</c> (run without screen refresh).</summary>
    void RenderBoneTree()
    {
        stage.engineObjectindex = 3;
        for (double i1 = 0, times1 = Round(Nz(stage.loadedBoneTree.Item(3).Num / stage.engineBoneattributes.Num)); i1 < times1; i1++)
        {
            if (!Eq(stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 7), 0))
            {
                stage.indexIndex1 = stage.loadedBoneTree.IndexOf(stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 7).Str + (".b-" + stage.loadedBoneTree.Item(2).Str));
            }
            else
            {
                stage.indexIndex1 = 0;
            }
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 8).Str + ".", "", ".", "", "");
            EngineUnsortedspriteCostumeSizeDirGbcIdBone(stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 1), stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 2), stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 3), "_icon.point", 0.5 + ((Nz(Sin(Timer * 500)) * 0.1) * Num(Eq(stage.modelGroup.Str + (".b-" + stage.loadedBoneTree.Item(2).Str), stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 8)))), 90, 50, 0, 90 * Num(Eq(stage.modelGroup.Str + (".b-" + stage.loadedBoneTree.Item(2).Str), stage.loadedBoneTree.Item(stage.engineObjectindex.Num + 8))), stage.decodedElements.Item(1), stage.loadedBoneTree.Item(2), stage.engineObjectindex, stage.indexIndex1);
            if (Eq(stage.engineClip, 0) && Gt(stage.indexIndex1, 0))
            {
                stage.indexIndex1 = stage.indexIndex1.Num - 8;
                SetPenSize(4 * Num(Gt(7 / stage.engineNewz.Num, 4)) + (Num(Lt(7 / stage.engineNewz.Num, 4)) * Nz(7 / stage.engineNewz.Num)));
                SetPenColor("#ffffff");
