                PenDown();
                stage.indexIndex2 = stage.loadedBoneTree.IndexOf(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 7).Str + (".b-" + stage.loadedBoneTree.Item(2).Str));
                EngineUnsortedspriteCostumeSizeDirGbcIdBone(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 1), stage.loadedBoneTree.Item(stage.indexIndex1.Num + 2), stage.loadedBoneTree.Item(stage.indexIndex1.Num + 3), "_icon.bone", 0, 90, 100, 0, 0, "", stage.loadedBoneTree.Item(2), stage.indexIndex1, stage.indexIndex2);
                PenUp();
