    /// <summary>Custom block <c>proccess: file</c> (run without screen refresh).</summary>
    void ProccessFile()
    {
        DataRecall();
        if (Eq(stage.decodedElements.Item(2), "create_file"))
        {
            if (stage.engineFiles.Contains(stage.dataVal1.Str + ".end"))
            {
                TerminalPrint("file \"" + (stage.dataVal1.Str + "\" already exists!"), 15);
            }
            else
            {
                if (Eq(stage.dataVal2, "true"))
                {
                    stage.tempFiles.Add(stage.dataVal1);
                }
                CreateFolder(stage.dataVal1);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "delete_file"))
        {
            if (stage.engineFiles.Contains(stage.dataVal1.Str + ".end"))
            {
                DeleteNameIfDataObject("file", stage.engineFiles.IndexOf(stage.dataVal1), "", "");
            }
            else
            {
                TerminalPrint("file \"" + (stage.dataVal1.Str + "\" doesn't exist."), 15);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "move_item"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                if (Gt(stage.engineFiles.IndexOf(stage.dataVal2), 0))
                {
                    TerminalPrint("move " + (stage.dataVal1.Str + (" to " + stage.dataVal2.Str)), 15);
                    EditAddress(33, 0);
                    Move("selectfile", stage.engineFiles.IndexOf(stage.dataVal2), "");
                    Move("selectdata", stage.fileLoadIndex.Num - 1, "");
                    EditAddress(34, stage.fileFolderIndex);
                    Move("move", "", "");
                }
                else
                {
                    TerminalPrint("file \"" + (stage.dataVal2.Str + "\" doesn't exsist."), 15);
                }
            }
            else
            {
                TerminalPrint("item \"" + (stage.dataVal1.Str + "\" doesn't exsist."), 15);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "copy_item"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                if (Gt(stage.engineFiles.IndexOf(stage.dataVal2), 0))
                {
                    TerminalPrint("copy " + (stage.dataVal1.Str + (" to " + (stage.dataVal2.Str + (" as " + stage.dataVal3.Str)))), 15);
                    EditAddress(33, 1);
                    Move("selectfile", stage.engineFiles.IndexOf(stage.dataVal2), "");
                    Move("selectdata", stage.fileLoadIndex.Num - 1, "");
                    EditAddress(34, stage.fileFolderIndex);
                    Move("move", "", stage.dataVal3);
                }
                else
                {
                    TerminalPrint("file \"" + (stage.dataVal2.Str + "\" doesn't exsist."), 15);
                }
            }
            else
            {
                TerminalPrint("item \"" + (stage.dataVal1.Str + "\" doesn't exsist."), 15);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "delete_item"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                DeleteNameIfDataObject("data", stage.fileLoadIndex.Num - 1, stage.fileFolderIndex, "");
                TerminalPrint("file: " + (stage.fileFolderIndex.Str + (", item: " + stage.fileLoadIndex.Str)), 15);
            }
            else
            {
                TerminalPrint("item \"" + (stage.dataVal1.Str + "\" doesn't exsist."), 15);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "create_item"))
        {
            if (Gt(stage.engineFiles.IndexOf(stage.dataVal3), 0))
            {
                if (Eq(stage.dataVal1, "model"))
                {
                    InsertDataToFile(stage.dataVal3, "model", stage.dataVal2.Str + ",3d,");
                }
                else
                {
                    InsertDataToFile(stage.dataVal3, stage.dataVal1, stage.dataVal2.Str + ",");
                }
            }
            else
            {
                TerminalPrint("file \"" + (stage.dataVal3.Str + "\" doesn't exsist."), 15);
            }
        }
    }

    /// <summary>Custom block <c>proccess: time</c> (run without screen refresh).</summary>
