    {
        if (Eq(stage.decodedElements.Item(2), "halt"))
        {
            TerminalPrint("program halted", -35);
            stage.scene.Replace(stage.objectIndex.Num + 31, "halt");
        }
        if (Eq(stage.decodedElements.Item(2), "timer"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", Timer, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "reset"))
        {
            ResetTimer();
            stage.timeTimer = Timer;
        }
        if (Eq(stage.decodedElements.Item(2), "ticks"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", Mod(stage.engineTick.Num, 999999), "set");
        }
        if (Eq(stage.decodedElements.Item(2), "ticks"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", Mod(Nz(Mod(stage.engineTick.Num, 10000000)), 999999), "set");
        }
        if (Eq(stage.decodedElements.Item(2), "timer_factor"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", Timer * stage.dataVal1.Num, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "tick_factor"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", Nz(Mod(stage.engineTick.Num, 10000000)) * stage.dataVal1.Num, "set");
        }
        if (Eq(stage.decodedElements.Item(2), "delta"))
        {
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
            if (Eq(stage.dataReturn, "null"))
            {
                InsertDataToObjectData(stage.scriptObject, "data_return", 0);
            }
            EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.timeDelta, "set");
        }
    }

