    /// <summary>Custom block <c>generate keyframe</c> (run without screen refresh).</summary>
    void GenerateKeyframe()
    {
        stage.indexIndex1 = 6;
        stage.keyframes.Add(stage.engineKeyframedelay);
        for (double i1 = 0, times1 = Round(Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num)); i1 < times1; i1++)
        {
            stage.keyframes.Add(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 5));
            stage.keyframes.Add(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 1));
            stage.keyframes.Add(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 2));
            stage.keyframes.Add(stage.loadedBoneTree.Item(stage.indexIndex1.Num + 3));
            stage.indexIndex1 = stage.indexIndex1.Num + stage.engineBoneattributes.Num;
        }
        stage.keyframes.Replace(1, stage.keyframes.Item(1).Num + 1);
    }

    /// <summary>Custom block <c>keyframe timeline</c> (run without screen refresh).</summary>
