            Render2DOnDirSizeGbcInteractiveShadowHoverMessage("_icon.star", 110 + (Nz((stage.keyframes.Item(1).Num - 1 - stage.indexIndex1.Num) / (stage.keyframes.Item(1).Num - 1)) * 110), -100 + (stage.ramEngineData.Item(2).Num * 1), 90, 25, 25, "", "", 1, "", "", 1, stage.keyframes.Item(2 + (stage.indexIndex1.Num * (1 + (4 * Nz(stage.loadedBoneTree.Item(3).Num / stage.engineBoneattributes.Num))))).Str + "s");
            stage.indexIndex1 = stage.indexIndex1.Num + 1;
        }
    }

    /// <summary>Custom block <c>generate animation</c> (run without screen refresh).</summary>
    void GenerateAnimation()
    {
        stage.loadedTextEditor.DeleteAll();
        stage.loadedTextEditor.Add("//" + (stage.animationName.Str + " was made with keyframe editor"));
        stage.loadedTextEditor.Add("//animation type: " + stage.ramEngineData.Item(200).Str);
        stage.loadedTextEditor.Add("model.set_bone(str " + (stage.loadedBoneTree.Item(2).Str + ")"));
        if (Eq(stage.ramEngineData.Item(200), "smooth"))
        {
            stage.loadedTextEditor.Add("model.ease(val 20)");
        }
        else
        {
            if (Eq(stage.ramEngineData.Item(200), "very fast"))
            {
                stage.loadedTextEditor.Add("model.ease(val 10)");
            }
            else
            {
                if (Eq(stage.ramEngineData.Item(200), "very smooth"))
                {
                    stage.loadedTextEditor.Add("model.ease(val 30)");
                }
                else
                {
                    if (Eq(stage.ramEngineData.Item(200), "instant"))
                    {
                        stage.loadedTextEditor.Add("model.ease(val 2)");
                    }
                    else
                    {
                        stage.loadedTextEditor.Add("model.ease(val 0)");
                    }
                }
            }
        }
        if (Eq(stage.ramEngineData.Item(202), 1))
        {
            stage.loadedTextEditor.Add("forever");
        }
        stage.loadedTextEditor.Add("//first keyframe");
        stage.loadedTextEditor.Add("var animate = val 0");
        stage.loadedTextEditor.Add("while (var animate < val 40)");
        stage.indexIndex1 = 2;
        for (double i1 = 0, times1 = Round(Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num)); i1 < times1; i1++)
        {
            DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.keyframes.Item(stage.indexIndex1.Num + 1), "", ".", "", "");
            stage.loadedTextEditor.Add("model.rotate_bone(val " + (stage.keyframes.Item(stage.indexIndex1.Num + 2).Str + (", val " + (stage.keyframes.Item(stage.indexIndex1.Num + 3).Str + (", val " + (stage.keyframes.Item(stage.indexIndex1.Num + 4).Str + (", str " + (stage.decodedElements.Item(1).Str + ")"))))))));
            stage.indexIndex1 = stage.indexIndex1.Num + 4;
        }
        stage.loadedTextEditor.Add("var animate += val 1");
        stage.loadedTextEditor.Add("wait (val 0.025)");
        stage.loadedTextEditor.Add("endwhile");
        stage.tempA1 = 2;
        stage.indexIndex1 = 2;
        for (double i1 = 0, times1 = Round(stage.keyframes.Item(1).Num - 1); i1 < times1; i1++)
        {
            stage.indexIndex1 = stage.indexIndex1.Num + (Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num) * 4 + 1);
            stage.loadedTextEditor.Add("//keyframe #" + stage.tempA1.Str);
            stage.indexIndex2 = stage.indexIndex1.Num + 1;
            stage.animationKeyframerotations = 0;
            for (double i2 = 0, times2 = Round(Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num)); i2 < times2; i2++)
            {
                if (((!Eq(stage.keyframes.Item(stage.indexIndex2.Num + 1), stage.keyframes.Item(stage.indexIndex2.Num + 1 - (Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num) * 4 + 1)))) || (!Eq(stage.keyframes.Item(stage.indexIndex2.Num + 2), stage.keyframes.Item(stage.indexIndex2.Num + 2 - (Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num) * 4 + 1))))) || (!Eq(stage.keyframes.Item(stage.indexIndex2.Num + 3), stage.keyframes.Item(stage.indexIndex2.Num + 3 - (Nz((stage.loadedBoneTree.Length - 3) / stage.engineBoneattributes.Num) * 1 + 3)))))
                {
                    stage.animationKeyframeheader = stage.loadedTextEditor.Length;
                    stage.animationKeyframerotations = stage.animationKeyframerotations.Num + 1;
                    DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.keyframes.Item(stage.indexIndex2), "", ".", "", "");
                    stage.loadedTextEditor.Add("model.rotate_bone(val " + (stage.keyframes.Item(stage.indexIndex2.Num + 1).Str + (", val " + (stage.keyframes.Item(stage.indexIndex2.Num + 2).Str + (", val " + (stage.keyframes.Item(stage.indexIndex2.Num + 3).Str + (", str " + (stage.decodedElements.Item(1).Str + ")"))))))));
                }
                stage.indexIndex2 = stage.indexIndex2.Num + 4;
            }
            if (Gt(stage.animationKeyframerotations, 0))
            {
                stage.loadedTextEditor.Insert(2 + (stage.animationKeyframeheader.Num - stage.animationKeyframerotations.Num), "while (var animate < val 40)");
                stage.loadedTextEditor.Insert(2 + (stage.animationKeyframeheader.Num - stage.animationKeyframerotations.Num), "var animate = val 0");
                stage.loadedTextEditor.Insert(4 + stage.animationKeyframeheader.Num, "endwhile");
                stage.loadedTextEditor.Insert(4 + stage.animationKeyframeheader.Num, "var animate += val 1");
                stage.loadedTextEditor.Insert(4 + stage.animationKeyframeheader.Num, "wait (val 0.025)");
            }
            if (Gt(stage.keyframes.Item(stage.indexIndex1), 0))
            {
                stage.loadedTextEditor.Add("wait (val " + (stage.keyframes.Item(stage.indexIndex1).Str + ")"));
            }
            stage.tempA1 = stage.tempA1.Num + 1;
        }
        if (Eq(stage.ramEngineData.Item(202), 1))
        {
            stage.loadedTextEditor.Add("endforever");
        }
        if (Eq(1, 1))
        {
            StartSound("Windows Vista Beta IRBegin");
            InsertDataToFile(stage.engineFiles.Item(stage.ramEngineData.Item(32)), "script", stage.animationName.Str + ",//empty");
            stage.textLoadedscript = stage.animationName;
            EngineSavescript(stage.animationName);
            stage.textLoadedscript = 0;
            stage.modelAnimating = 0;
        }
    }

