    /// <summary>Custom block <c>proccess: list</c> (run without screen refresh).</summary>
    void ProccessList()
    {
        DataRecall();
        if (Eq(stage.decodedElements.Item(2), "create_list"))
        {
            if (stage.engineFiles.Contains(stage.dataVal2.Str + ".end"))
            {
                InsertDataToFile(stage.dataVal2, "list", stage.dataVal1.Str + ",");
                EditAddress(16, 1);
            }
            else
            {
                TerminalPrint("file \"" + (stage.dataVal2.Str + "\" doesn't exist!"), 25);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "clear"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                DeleteNameIfDataObject("data", stage.fileLoadIndex.Num - 1, stage.fileFolderIndex, "");
                InsertDataToFile(stage.engineFiles.Item(stage.fileFolderIndex), "list", stage.dataVal1.Str + ",");
            }
            else
            {
                TerminalPrint("list \"" + (stage.dataVal1.Str + "\" doesn't exist!"), 25);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "add_item"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                stage.tempTemp3 = stage.engineFiles.Item(stage.fileLoadIndex);
                DeleteNameIfDataObject("data", stage.fileLoadIndex.Num - 1, stage.fileFolderIndex, "");
                InsertDataToFile(stage.engineFiles.Item(stage.fileFolderIndex), "list", stage.tempTemp3.Str + (stage.dataVal2.Str + ","));
            }
            else
            {
                TerminalPrint("list \"" + (stage.dataVal1.Str + "\" doesn't exist!"), 25);
            }
        }
        if (Eq(stage.decodedElements.Item(2), "read"))
        {
            FileFindData(stage.dataVal1);
            if (Eq(stage.fileFound, 1))
            {
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", 0, "read");
                if (Eq(stage.dataReturn, "null"))
                {
                    InsertDataToObjectData(stage.scriptObject, "data_return", 0);
                }
                DecodeIDSeperatorIncludeSeperatorSpecialdot(stage.engineFiles.Item(stage.fileLoadIndex), "", ",", "", "");
                EditDataInObjectDataOperation(stage.scriptObject, "data_return", stage.decodedElements.Item(stage.dataVal2.Num + 1), "set");
