            else
            {
                TerminalPrint("list \"" + (stage.dataVal1.Str + "\" doesn't exist!"), 25);
            }
        }
    }

    /// <summary>Custom block <c>Main Key detection</c> (run without screen refresh).</summary>
    void MainKeyDetection()
    {
        if (Gt(stage.inputAddress, 0))
        {
            DetectKeyGame(0, "");
        }
        else
        {
            if (Eq(stage.editorTab, "script") && Eq(stage.textEditor, 1))
            {
                DetectKeyGame(1, "");
                if (Gt(stage.inputKey, ""))
                {
                    EditorInsertletterDelete(stage.textCursorx, stage.textCursory, stage.inputKey, "");
                    stage.textCursorx = stage.textCursorx.Num + 1;
                    stage.inputKey = "";
                }
                else
                {
                    if (KeyPressed("backspace" + ""))
                    {
                        if (Eq(stage.loadedTextEditor.Item(stage.textCursory.Num + 1), "") && Gt(stage.loadedTextEditor.Length, 1))
                        {
                            stage.loadedTextEditor.Delete(stage.textCursory.Num + 1);
                            if (Gt(stage.textCursory, 0))
                            {
                                stage.textCursory = stage.textCursory.Num + -1;
                            }
                        }
                        else
                        {
                            if (Gt(stage.textCursorx, 0))
                            {
                                EditorInsertletterDelete(stage.textCursorx, stage.textCursory, stage.inputKey, 1);
                                stage.textCursorx = stage.textCursorx.Num + -1;
                            }
                            else
                            {
                                EditorInsertletterDelete(stage.textCursorx.Num + 1, stage.textCursory, stage.inputKey, 1);
                            }
                        }
                    }
                    else
                    {
                        if (KeyPressed("enter" + ""))
                        {
                            if (Eq(stage.textCursorx, 0))
                            {
                                stage.loadedTextEditor.Insert(stage.textCursory.Num + 1, "");
                            }
                            else
                            {
                                stage.loadedTextEditor.Insert(stage.textCursory.Num + 2, "");
                            }
                            stage.textCursory = stage.textCursory.Num + 1;
                        }
                    }
                }
                stage.textCursory = stage.textCursory.Num + ((Num(KeyPressed("down arrow")) - Num(KeyPressed("up arrow"))) * 1);
                stage.textCursory = Mod(stage.textCursory.Num, stage.loadedTextEditor.Length);
                stage.textCursorx = stage.textCursorx.Num + ((Num(KeyPressed("right arrow")) - Num(KeyPressed("left arrow"))) * 1);
                stage.textCursorx = Mod(stage.textCursorx.Num, stage.loadedTextEditor.Item(stage.textCursory.Num + 1).Str.Length + 1);
                if (KeyPressed("`" + "") && Eq(stage.ramEngineData.Item(26), 0))
                {
                    stage.textAutocompleteresurrect = 1;
                }
            }
        }
        if (Eq(stage.allExportState, 0))
        {
            if (KeyPressed("page up" + ""))
            {
                StartSound("Windows Hardware Insert");
                ShowList(stage.engineFiles);
            }
            if (KeyPressed("page down" + ""))
            {
                StartSound("Windows Hardware Remove");
                HideList(stage.engineFiles);
            }
        }
    }

}
